        $itemsLogin = array();
        $itemsLock = array();
        $warning = array();
        $marking = array();
        $markingColumn = array();

        $userByMembership = array();
        if (sizeof($arrUser) > 0) {
//                        arrPrintWebs($arrUser);
            //            arrPrintWebs($arrTrData);
            foreach ($arrUser as $trSpec_s) {
                $trSpec = (object)$trSpec_s;

                $subItems['pID'] = $trSpec->id;
                foreach ($headerFields as $key => $val) {
