        }
        //------------------------------------------------------
        $headerFields = array(
            "pID" => "pID",
            "pName" => "product",
            "kredit" => "rek kredit",
            "pymSrc" => "pym src",
            "pymASrc" => "pym anti<br>src",
            "netto" => "netto",
            "selisih" => "selisih",
        );
        $nof = 0;
        $items = array();
        $warning = array();
        $marking = array();
        $markingColumn = array();
        if (sizeof($products) > 0) {

            $this->db->trans_start();

            foreach ($products as $pID => $pSpec) {

                $jmlRek = isset($pSpec['kredit']) ? $pSpec['kredit'] : 0;
                $jmlPymSrc = isset($srcData[$pID]) ? $srcData[$pID] : 0;
