                    ),
                );

                $bg_color = "";
                $add = "";
                //                if ($jmlLoker != $pSpec['stock']) {
                //                    $bg_color = "background-color:yellow;";
                //                    $add = "<span style='text-align: right;font-size: 10px;'> ::: ( yellow )</span>";
                //                }

                $nof++;
                if (round($jmlRek, 2) != round($jmlPymSrc, 2)) {
                    $marking[$pID] = array(
                        "add_name" => "(yellow)",
                        "background-color" => "yellow",
                    );
                }


                //                if ($pSpec['stock'] != $jmlLoker) {

                //                    $marking[$pID] = array(
                //                        "add_name" => "(yellow)",
                //                        "background-color" => "yellow",
                //                    );

                //hilangkan saja
                //                    $ll = new MdlLockerValue();
                //                    $ll->updateData(
                //                        array(
                //                            "jenis" => "kas",
                //                            "jenis_locker" => "value",
                //                            "cabang_id" => $branchID,
                //                            "gudang_id" => $whID,
                //                            "produk_id" => $pID,
                //                            "transaski_id" => 0,
                //                            "state" => "active",
                //                        ), array(
                ////                            "produk_id" => 6666,
                //                            "nilai" => $jmlActive_new,
                ////                            "nama" => "unknown",
                ////                            "state" => "dest",
                //                        )
                //                    );
                //                    $update = $this->db->last_query() . ";";
                //
                //
