                //                $antiSrcNumber = isset($antiSrcData[$pID]['nomer']) ? $antiSrcData[$pID]['nomer'] : "-";
                $bayar = isset($arrBayarItem[$pID]) ? $arrBayarItem[$pID] : 0;
                $sisa = ($rekNilai - $bayar) > 0 ? $rekNilai - $bayar : 0;


                $items[] = array(
                    "pID" => $pID,
                    "dtime" => $invSpec['dtime'],
                    "debet" => $rekNilai,
