        $p->setFilters(array());
        $p->addFilter("jenis<>'folder'");
        $pTmp = $p->lookupAll()->result();
        $arrKategori = array();
        foreach ($pTmp as $pTmpSpec) {
            $arrKategori[$pTmpSpec->id] = array(
                "id" => $pTmpSpec->kategori_id,
                "nama" => $pTmpSpec->kategori_nama,
