            $trInum = $temp[0]->transaksi_no;
            $t->setFilters(array());
            $t->addFIlter("transaksi_id='$trID'");
            $temReg = $t->lookupDataRegistries()->result();
            $items4 = blobDecode($temReg[0]->items4_sum);

            $items = array();
