        }
        .step-pill-1 { background: #e0e7ff; color: #3730a3; border: 1px solid #c7d2fe; } /* Input/Draft */
        .step-pill-2 { background: #fef3c7; color: #92400e; border: 1px solid #fde68a; } /* Approve */
        .step-pill-3 { background: #ede9fe; color: #6d28d9; border: 1px solid #ddd6fe; } /* Packing */
        .step-pill-4 { background: #dbeafe; color: #1e40af; border: 1px solid #bfdbfe; } /* Delivery */
        .step-pill-5 { background: #dcfce7; color: #166534; border: 1px solid #bbf7d0; } /* Invoice */
        .step-pill-sod { background: #fee2e2; color: #991b1b; border: 1px solid #fca5a5; font-weight: 800; } /* Dual Role SoD Conflict */

        /* Role Pills */
        .role-pill {
            display: inline-block;
            color: #ffffff;
            font-size: 10px;
            font-weight: 600;
            padding: 2px 8px;
            border-radius: 12px;
            margin: 2px 4px 2px 0;
            letter-spacing: 0.2px;
        }
        .role-pill-empty { color: #94a3b8; font-style: italic; font-size: 11px; }
        .role-count-badge {
            background: #e2e8f0;
            color: #475569;
            font-size: 10px;
            font-weight: 700;
            padding: 1px 6px;
            border-radius: 8px;
            margin-right: 4px;
        }

        /* Modal Details */
        .modal-overlay {
            display: none;
            position: fixed;
            top: 0; left: 0; right: 0; bottom: 0;
            background: rgba(15, 23, 42, 0.6);
            backdrop-filter: blur(2px);
            z-index: 999;
            align-items: center;
            justify-content: center;
            padding: 20px;
        }
        .modal-container {
            background: #ffffff;
            border-radius: 12px;
            max-width: 1020px;
            width: 100%;
            max-height: 90vh;
            overflow-y: auto;
            box-shadow: 0 20px 25px -5px rgba(0,0,0,0.2);
            border: 1px solid #cbd5e1;
            position: relative;
        }
        .modal-header {
            padding: 18px 24px;
            border-bottom: 1px solid #e2e8f0;
            display: flex;
            justify-content: space-between;
            align-items: center;
            background: #f8fafc;
            border-radius: 12px 12px 0 0;
            position: sticky;
            top: 0;
            z-index: 5;
        }
        .modal-header h3 { font-size: 16px; font-weight: 700; color: #0f172a; }
        .modal-header .btn-close {
            background: transparent;
            border: none;
            font-size: 20px;
            font-weight: bold;
            color: #64748b;
            cursor: pointer;
            padding: 4px 8px;
            border-radius: 4px;
        }
        .modal-header .btn-close:hover { background: #e2e8f0; color: #0f172a; }
        .modal-body { padding: 24px; }

        .modal-grid {
            display: grid;
            grid-template-columns: repeat(2, 1fr);
            gap: 14px;
            margin-bottom: 20px;
            background: #f8fafc;
            padding: 16px;
            border-radius: 8px;
            border: 1px solid #e2e8f0;
        }
        .detail-item { font-size: 12px; }
        .detail-label { font-weight: 600; color: #64748b; text-transform: uppercase; font-size: 10px; margin-bottom: 2px; }
        .detail-val { font-weight: 600; color: #0f172a; font-size: 13px; }

        .modal-tab-nav {
            display: flex;
            gap: 8px;
            margin-bottom: 16px;
            border-bottom: 2px solid #e2e8f0;
            padding-bottom: 0;
        }
        .modal-tab-btn {
            padding: 9px 16px;
            border-radius: 6px 6px 0 0;
            background: #f1f5f9;
            border: 1px solid #e2e8f0;
            border-bottom: none;
            font-weight: 700;
            font-size: 12px;
            color: #64748b;
            cursor: pointer;
            transition: all 0.2s;
        }
        .modal-tab-btn.active {
            background: #4f46e5;
            color: #ffffff;
            border-color: #4f46e5;
        }
        .modal-tab-panel { display: none; }
        .modal-tab-panel.active { display: block; }

        .modal-role-table {
            width: 100%;
            border-collapse: collapse;
            font-size: 12px;
            border: 1px solid #e2e8f0;
            border-radius: 6px;
            overflow: hidden;
        }
        .modal-role-table th { background: #f1f5f9; padding: 8px 12px; text-align: left; font-weight: 700; color: #475569; }
        .modal-role-table td { padding: 8px 12px; border-top: 1px solid #e2e8f0; }

        .raw-box {
            background: #0f172a;
            color: #38bdf8;
            padding: 12px;
            border-radius: 6px;
            font-family: monospace;
            font-size: 11px;
            white-space: pre-wrap;
            word-break: break-all;
            max-height: 140px;
            overflow-y: auto;
            margin-top: 10px;
        }

        @keyframes fadeIn {
            from { opacity: 0; transform: translateY(-4px); }
            to { opacity: 1; transform: translateY(0); }
        }

        /* Print styles */
        @media print {
            body { padding: 0; background: #fff; }
            .top-actions, .filter-card, .filter-cloud-card, .step-sub-bar, .btn-action, .modal-overlay { display: none !important; }
            .top-bar { box-shadow: none; border: none; padding: 0; margin-bottom: 15px; }
            .table-card { box-shadow: none; border: 1px solid #ccc; }
        }
    </style>
</head>
<body>

<div class='container'>
    <!-- Top Header -->
    <div class='top-bar'>
        <div>
            <h1>🔐 Monitoring Hak Akses &amp; Alur Kerja (Workflow Step Matrix)</h1>
            <p>Audit terpadu peran pengguna dari <code>per_employee</code> dan pembagian tugas per tahapan workflow (Create, Approve, Packing, Kirim, Invoice) dari <code>set_menu</code></p>
        </div>
        <div class='top-actions'>
            <button class='btn btn-secondary' onclick='window.print();'>🖨️ Cetak</button>
            <button class='btn btn-success' onclick='exportToCSV();'>📥 Export CSV</button>
            <button class='btn btn-primary' onclick='window.location.reload();'>🔄 Segarkan</button>
        </div>
    </div>

    <!-- Summary KPI Cards -->
    <div class='kpi-grid'>
        <div class='kpi-card blue'>
            <div class='kpi-title'>Total Karyawan</div>
            <div class='kpi-value'>" . number_format($totalEmployees) . "</div>
            <div class='kpi-sub'><b>" . number_format($activeEmployees) . "</b> Aktif &bull; <b>" . number_format($inactiveEmployees) . "</b> Nonaktif</div>
        </div>
        <div class='kpi-card green'>
            <div class='kpi-title'>Memiliki Hak Akses Menu</div>
            <div class='kpi-value'>" . number_format($withMenusCount) . "</div>
            <div class='kpi-sub'>Karyawan dengan izin menu di <code>set_menu</code></div>
        </div>
        <div class='kpi-card indigo'>
            <div class='kpi-title'>Total Izin Menu Aktif</div>
            <div class='kpi-value'>" . number_format($totalActiveMenuRules) . "</div>
            <div class='kpi-sub'>Aturan step transaksi terdaftar</div>
        </div>
        <div class='kpi-card purple'>
            <div class='kpi-title'>Total Menu Alur Kerja</div>
            <div class='kpi-value'>" . number_format(count($menuWorkflowCatalog)) . "</div>
            <div class='kpi-sub'>Fitur transaksi multi-tahap</div>
        </div>
        <div class='kpi-card rose'>
            <div class='kpi-title'>Sesi Login Aktif</div>
            <div class='kpi-value'>" . number_format($onlineCount) . "</div>
            <div class='kpi-sub'>Karyawan status_login = 1</div>
        </div>
    </div>

    <!-- WORKFLOW MENU & STEP QUICK FILTER (SEPARATION OF DUTIES) -->
    <div class='filter-cloud-card'>
        <div class='filter-cloud-header'>
            <span class='filter-cloud-title'>🧭 Filter Cepat Menu &amp; Tahapan Workflow (Segregation of Duties):</span>
            <span class='filter-cloud-hint'>Pilih menu untuk melihat siapa saja yang memegang Step 1 (Input), Step 2 (Approve), Step 3 (Packing), Step 4 (Kirim), Step 5 (Invoice)</span>
        </div>
        <div class='filter-cloud-list' id='menuWorkflowList'>
            <div class='chip-btn active' id='chipMenuAll' onclick='selectWorkflowMenu(\"\")'>
                🌐 Semua Menu <span class='count'>" . number_format($totalEmployees) . "</span>
            </div>";

        // Top 8 Populer Menu Multi-Step
        $featuredMenus = array(
            'sales' => '🛒 Sales / Penjualan (582)',
            'FG purchasing' => '🏢 FG Purchasing (466)',
            '#1 distribusi FG (project)' => '🚚 Distribusi FG Project (5833)',
            'international sales' => '🌍 International Sales (382)',
            'destock (to other warehouse branch)' => '📦 Destock Cabang (587)',
            'sales return' => '🔄 Sales Return (982)',
            'stok opname produk (branch)' => '📊 Stock Opname (2229)',
            'biaya usaha' => '💸 Biaya Usaha (677)',
            'service purchasing' => '🛠️ Service Purchasing (463)'
        );

        foreach ($featuredMenus as $fKey => $fLabel) {
            if (isset($menuWorkflowCatalog[$fKey])) {
                $uCount = count($menuWorkflowCatalog[$fKey]['users']);
                echo "<div class='chip-btn' data-menu='" . htmlspecialchars($fKey) . "' onclick='selectWorkflowMenu(\"" . htmlspecialchars($fKey) . "\")'>";
                echo $fLabel . " <span class='count'>" . $uCount . "</span>";
                echo "</div>";
            }
        }

        echo "</div>

        <!-- STEP SUB-FILTER (Dinamis Muncul saat Menu Dipilih) -->
        <div class='step-sub-bar' id='stepSubBar'>
            <div class='step-sub-title'>
                <span>🎯 Tahapan Otorisasi pada Menu: <strong id='activeMenuTitle'>-</strong></span>
                <span style='font-size:11px; font-weight:normal; color:#64748b;'>Klik tahapan di bawah untuk menyaring siapa saja pemegang wewenang tersebut:</span>
            </div>
            <div class='filter-cloud-list' id='stepButtonsList'></div>
        </div>
    </div>

    <!-- Role Quick Filter Cloud -->
    <div class='filter-cloud-card'>
        <div class='filter-cloud-header'>
            <span class='filter-cloud-title'>🏷️ Distribusi Role Akun (Membership):</span>
            <span class='filter-cloud-hint'>Klik role akun untuk menyaring tabel</span>
        </div>
        <div class='filter-cloud-list' id='roleCloudList'>
            <div class='chip-btn active' data-role='' onclick='filterByRoleChip(\"\")'>
                Semua Role <span class='count'>" . number_format($totalEmployees) . "</span>
            </div>
            <div class='chip-btn' data-role='__EMPTY__' onclick='filterByRoleChip(\"__EMPTY__\")'>
                🚫 Tanpa Role <span class='count'>" . number_format($withoutRolesCount) . "</span>
            </div>";

        $maxShowRoles = 12;
        $counter = 0;
        foreach ($allRolesCount as $rKey => $rCount) {
            $desc = isset($roleDescriptions[$rKey]) ? $roleDescriptions[$rKey] : '';
            $lbl = htmlspecialchars($rKey);
            $titleAttr = htmlspecialchars($desc !== '' ? $desc : $rKey);
            echo "<div class='chip-btn' data-role='" . $lbl . "' title='" . $titleAttr . "' onclick='filterByRoleChip(\"" . $lbl . "\")'>";
            echo $lbl . " <span class='count'>" . $rCount . "</span>";
            echo "</div>";
            $counter++;
            if ($counter >= $maxShowRoles) {
                break;
            }
        }

        echo "</div>
    </div>

    <!-- Active Filter Alert Bar -->
    <div class='active-filter-alert' id='activeFilterBar'>
        <div>
            <span>🔍 <strong>Filter Aktif:</strong> Menampilkan karyawan dengan akses </span>
            <strong id='filterBreadcrumbText'>-</strong>
        </div>
        <button class='btn btn-secondary btn-sm' onclick='resetFilters()'>✕ Hapus Filter</button>
    </div>

    <!-- Filter Bar -->
    <div class='filter-card'>
        <div class='filter-row'>
            <div class='filter-group search'>
                <label>Pencarian Bebas</label>
                <input type='text' id='filterSearch' class='filter-input' placeholder='Cari Nama, Username, ID, Cabang, Modul, Menu, Step...' oninput='applyFilters()'>
            </div>
            <div class='filter-group'>
                <label>Menu / Transaksi</label>
                <select id='filterMenuSelect' class='filter-select' onchange='onMenuSelectChange()'>
                    <option value=''>Semua Menu Transaksi (" . count($menuWorkflowCatalog) . ")</option>";
                    foreach ($menuWorkflowCatalog as $mKey => $mData) {
                        echo "<option value='" . htmlspecialchars($mKey) . "'>" . htmlspecialchars($mKey) . " (" . count($mData['users']) . " user)</option>";
                    }
                echo "</select>
            </div>
            <div class='filter-group'>
                <label>Tahapan / Step Workflow</label>
                <select id='filterStepSelect' class='filter-select' onchange='onStepSelectChange()'>
                    <option value=''>Semua Tahapan</option>
                </select>
            </div>
            <div class='filter-group'>
                <label>Modul Menu</label>
                <select id='filterModule' class='filter-select' onchange='applyFilters()'>
                    <option value=''>Semua Modul</option>
                    <option value='__WITH_MENU__'>✅ Punya Akses Menu (&gt;0)</option>
                    <option value='__NO_MENU__'>🚫 Tanpa Akses Menu (0)</option>";
                    foreach ($allDistinctModules as $modKey => $bVal) {
                        echo "<option value='" . htmlspecialchars($modKey) . "'>" . htmlspecialchars(ucwords($modKey)) . "</option>";
                    }
                echo "</select>
            </div>
            <div class='filter-group'>
                <label>Status Karyawan</label>
                <select id='filterStatus' class='filter-select' onchange='applyFilters()'>
                    <option value=''>Semua Status</option>
                    <option value='aktif' selected>Aktif Normal (trash = 0)</option>
                    <option value='inaktif'>Non-Aktif (status = 0)</option>
                    <option value='trash'>Terhapus (trash = 1)</option>
                </select>
            </div>
            <div style='padding-top: 18px;'>
                <button class='btn btn-secondary' onclick='resetFilters()'>🔄 Reset</button>
            </div>
        </div>
        <div class='filter-info-bar'>
            <div class='filter-info-count'>
                Menampilkan <strong id='countShowing'>" . number_format($activeEmployees) . "</strong> dari <strong>" . number_format($totalEmployees) . "</strong> karyawan
            </div>
            <div style='font-size:11px;'>
                Scope Role: 
                <span class='role-pill' style='background:#0284c7;'>c_* Pusat</span>
                <span class='role-pill' style='background:#059669;'>o_* Cabang</span>
                <span class='role-pill' style='background:#d97706;'>w_* Gudang</span>
                <span class='role-pill' style='background:#7c3aed;'>p_* Produksi</span>
                <span class='role-pill' style='background:#e11d48;'>root/sys System</span>
            </div>
        </div>
    </div>

    <!-- Data Table -->
    <div class='table-card'>
        <div class='table-responsive'>
            <table class='employee-table' id='empTable'>
                <thead>
                    <tr>
                        <th style='width:50px; text-align:center;'>No</th>
                        <th style='width:60px; text-align:center;'>ID</th>
                        <th style='width:220px;'>Karyawan</th>
                        <th style='width:160px;'>Tipe &amp; Lokasi</th>
                        <th style='width:100px; text-align:center;'>Status</th>
                        <th style='width:220px;'>Role Membership</th>
                        <th>Otorisasi Tahapan Workflow (set_menu)</th>
                        <th style='width:100px; text-align:center;'>Aksi</th>
                    </tr>
                </thead>
                <tbody id='tableBody'>";

                $rowNum = 1;
                foreach ($employeeList as $idx => $emp) {
                    $statusBadge = '';
                    if ($emp['trash'] === 1) {
                        $statusBadge = "<span class='badge badge-trash'>TRASH</span>";
                    } elseif ($emp['status'] === 1) {
                        $statusBadge = "<span class='badge badge-active'>AKTIF</span>";
                    } else {
                        $statusBadge = "<span class='badge badge-inactive'>NONAKTIF</span>";
                    }

                    $flags = '';
                    if ($emp['ghost'] === 1) {
                        $flags .= " <span class='badge badge-ghost' title='Ghost User'>👻 Ghost</span>";
                    }
                    if ($emp['suspend'] === 1) {
                        $flags .= " <span class='badge badge-trash' title='Akun Disuspend'>⛔ Suspend</span>";
                    }
                    if ($emp['status_login'] === 1) {
                        $flags .= " <span class='badge badge-active' title='Sedang Login'>🟢 Online</span>";
                    }

                    // Render roles badges
                    $roleHtml = '';
                    $roleCount = count($emp['roles']);
                    if ($roleCount > 0) {
                        $roleHtml .= "<span class='role-count-badge'>" . $roleCount . " role</span>";
                        foreach ($emp['roles'] as $r) {
                            $desc = isset($roleDescriptions[$r]) ? $roleDescriptions[$r] : '';
                            $roleHtml .= $renderRoleBadge($r, $desc);
                        }
                    } else {
                        $roleHtml = "<span class='role-pill-empty'>Tidak ada role membership</span>";
                    }

                    // Dynamic Workflow Container per row
                    $wfHtml = "<div class='row-workflow-summary' id='wfSummary_" . $idx . "'>";
                    if ($emp['menu_total'] > 0) {
                        $wfHtml .= "<div style='margin-bottom:4px;'><span class='badge-menu-count'>" . $emp['menu_total'] . " Menu Izin</span></div>";
                        $showModCount = 0;
                        foreach ($emp['menu_modules'] as $modName) {
                            $wfHtml .= "<span class='badge-module'>" . htmlspecialchars($modName) . "</span>";
                            $showModCount++;
                            if ($showModCount >= 3 && count($emp['menu_modules']) > 3) {
                                $wfHtml .= "<span style='font-size:10px; color:#64748b;'>+" . (count($emp['menu_modules']) - 3) . " lagi</span>";
                                break;
                            }
                        }
                    } else {
                        $wfHtml .= "<span class='role-pill-empty'>Belum ada izin di set_menu</span>";
                    }
                    $wfHtml .= "</div>";

                    $searchKeywords = strtolower($emp['id'] . ' ' . $emp['nama_login'] . ' ' . $emp['nama'] . ' ' . $emp['cabang_nama'] . ' ' . $emp['div_name'] . ' ' . $emp['employee_type'] . ' ' . $emp['jenis'] . ' ' . implode(' ', $emp['roles']) . ' ' . implode(' ', $emp['menu_modules']));

                    echo "<tr class='emp-row' 
                              data-idx='" . $idx . "'
                              data-id='" . $emp['id'] . "'
                              data-type='" . htmlspecialchars($emp['employee_type']) . "'
                              data-cabang='" . htmlspecialchars($emp['cabang_nama']) . "'
                              data-status='" . $emp['status_key'] . "'
                              data-roles='" . htmlspecialchars(implode(',', $emp['roles'])) . "'
                              data-modules='" . htmlspecialchars(implode(',', $emp['menu_modules'])) . "'
                              data-menu-count='" . $emp['menu_total'] . "'
                              data-search='" . htmlspecialchars($searchKeywords) . "'>";
                    
                    echo "<td style='text-align:center;' class='row-num'>" . $rowNum++ . "</td>";
                    echo "<td style='text-align:center;'><strong>#" . $emp['id'] . "</strong></td>";
                    
                    echo "<td>";
                    echo "<div class='user-title'>" . htmlspecialchars($emp['nama']) . "</div>";
                    echo "<div class='user-sub'>@" . htmlspecialchars($emp['nama_login']);
                    if ($emp['jenis'] !== '') {
                        echo " &bull; <i>" . htmlspecialchars($emp['jenis']) . "</i>";
                    }
                    echo "</div>";
                    echo "</td>";

                    echo "<td>";
                    echo "<div><span class='badge badge-type'>" . htmlspecialchars($emp['employee_type']) . "</span></div>";
                    if ($emp['cabang_nama'] !== '') {
                        echo "<div class='loc-cabang' style='margin-top:4px;'>🏢 " . htmlspecialchars($emp['cabang_nama']) . "</div>";
                    }
                    if ($emp['div_name'] !== '') {
                        echo "<div class='loc-div'>📁 " . htmlspecialchars($emp['div_name']) . "</div>";
                    }
                    echo "</td>";

                    echo "<td style='text-align:center;'>" . $statusBadge . $flags . "</td>";
                    echo "<td>" . $roleHtml . "</td>";
                    echo "<td>" . $wfHtml . "</td>";

                    echo "<td style='text-align:center;'>";
                    echo "<button class='btn btn-secondary btn-sm btn-action' onclick='showEmployeeDetail(" . $idx . ")'>👁️ Detail &amp; Menu</button>";
                    echo "</td>";

                    echo "</tr>";
                }

                echo "</tbody>
            </table>
        </div>
    </div>
</div>

<!-- Modal Detail Karyawan & Menu Modul -->
<div class='modal-overlay' id='detailModal' onclick='handleModalOverlayClick(event)'>
    <div class='modal-container' id='modalContainer'>
        <div class='modal-header'>
            <div>
                <h3 id='modalTitle'>Detail Hak Akses &amp; Menu Karyawan</h3>
                <div id='modalSubtitle' style='font-size:12px; color:#64748b; margin-top:2px;'></div>
            </div>
            <button class='btn-close' onclick='closeModal()'>&times;</button>
        </div>
        <div class='modal-body'>
            <div class='modal-grid' id='modalGrid'></div>
            
            <!-- Modal Internal Tabs -->
            <div class='modal-tab-nav'>
                <div class='modal-tab-btn active' id='btnTabMenu' onclick='switchModalTab(\"modalTabMenu\")'>📋 Izin Menu Modul (set_menu: <span id='modalMenuCountBadge'>0</span>)</div>
                <div class='modal-tab-btn' id='btnTabRole' onclick='switchModalTab(\"modalTabRole\")'>🔐 Role Membership (<span id='modalRoleCountBadge'>0</span>)</div>
                <div class='modal-tab-btn' id='btnTabRaw' onclick='switchModalTab(\"modalTabRaw\")'>⚙️ Raw Data (JSON)</div>
            </div>

            <!-- Tab 1: Menu & Modul -->
            <div id='modalTabMenu' class='modal-tab-panel active'>
                <div style='display:flex; justify-content:space-between; align-items:center; margin-bottom:12px;'>
                    <input type='text' id='searchModalMenu' class='filter-input' style='max-width:320px;' placeholder='🔍 Cari nama menu / modul / step...' oninput='filterModalMenuItems()'>
                    <div id='modalModulesSummary' style='display:flex; gap:6px; flex-wrap:wrap;'></div>
                </div>
                <div id='modalMenuTableContainer' style='max-height:380px; overflow-y:auto;'></div>
            </div>

            <!-- Tab 2: Role Membership -->
            <div id='modalTabRole' class='modal-tab-panel'>
                <div id='modalRolesTableContainer'></div>
            </div>

            <!-- Tab 3: Raw Data -->
            <div id='modalTabRaw' class='modal-tab-panel'>
                <h4 style='font-size:11px; color:#475569; text-transform:uppercase;'>Decoded Membership JSON</h4>
                <div class='raw-box' id='modalRawBox'></div>
                <h4 style='font-size:11px; color:#475569; text-transform:uppercase; margin-top:14px;'>Configured set_menu Items JSON</h4>
                <div class='raw-box' id='modalMenuRawBox'></div>
            </div>
        </div>
    </div>
</div>

<script>
    var employeesData = " . $jsonEmployees . ";
    var roleDescriptions = " . $jsonRoleDesc . ";
    var menuWorkflowCatalog = " . $jsonMenuCatalog . ";
    
    var currentRoleFilter = '';
    var currentMenuFilter = '';
    var currentStepFilter = '';
    var currentSoDFilter = false;
    var currentModalEmployee = null;

    function getRoleScope(role) {
        if (role.indexOf('c_') === 0) return { name: 'Pusat (Center)', color: '#0284c7' };
        if (role.indexOf('o_') === 0) return { name: 'Cabang (Outlet)', color: '#059669' };
        if (role.indexOf('w_') === 0) return { name: 'Gudang (Warehouse)', color: '#d97706' };
        if (role.indexOf('p_') === 0) return { name: 'Produksi (Production)', color: '#7c3aed' };
        if (role === 'root' || role === 'admin' || role === 'superman') return { name: 'System / Superadmin', color: '#e11d48' };
        return { name: 'Lainnya', color: '#64748b' };
    }

    function selectWorkflowMenu(menuKey) {
        currentMenuFilter = menuKey;
        currentStepFilter = '';
        currentSoDFilter = false;

        document.getElementById('filterMenuSelect').value = menuKey;

        // Update active class on menu chips
        var chips = document.querySelectorAll('#menuWorkflowList .chip-btn');
        for (var i = 0; i < chips.length; i++) {
            var m = chips[i].getAttribute('data-menu') || '';
            if (m === menuKey) {
                chips[i].classList.add('active');
            } else {
                chips[i].classList.remove('active');
            }
        }

        var subBar = document.getElementById('stepSubBar');
        var stepSelect = document.getElementById('filterStepSelect');
        stepSelect.innerHTML = '<option value=\"\">Semua Tahapan</option>';

        if (menuKey !== '' && menuWorkflowCatalog[menuKey]) {
            var mData = menuWorkflowCatalog[menuKey];
            document.getElementById('activeMenuTitle').innerText = menuKey.toUpperCase() + ' (' + mData.user_count + ' User)';
            
            var stepBtnsHtml = '';
            stepBtnsHtml += '<div class=\"chip-btn active-step\" id=\"stepChipAll\" data-step=\"\" onclick=\"selectWorkflowStep(this.getAttribute(&quot;data-step&quot;))\">🔘 Semua Tahapan (' + mData.user_count + ')</div>';

            // Check if has Step 1 & Step 2 for SoD
            var hasStep1 = false;
            var hasStep2 = false;

            for (var s = 0; s < mData.steps.length; s++) {
                var st = mData.steps[s];
                if (st.step_no == 1) hasStep1 = true;
                if (st.step_no == 2) hasStep2 = true;

                var stepLabelDesc = getStepSemanticLabel(st.step_no, st.step_label);
                stepBtnsHtml += '<div class=\"chip-btn\" data-step=\"' + st.step_no + '\" onclick=\"selectWorkflowStep(this.getAttribute(&quot;data-step&quot;))\">' + stepLabelDesc + ' <span class=\"count\">' + st.user_count + '</span></div>';
                
                stepSelect.innerHTML += '<option value=\"' + st.step_no + '\">Step ' + st.step_no + ' - ' + st.step_label + ' (' + st.user_count + ' user)</option>';
            }

            if (hasStep1 && hasStep2) {
                stepBtnsHtml += '<div class=\"chip-btn\" id=\"chipSoD\" style=\"border-color:#fca5a5; color:#991b1b;\" onclick=\"toggleSoDFilter()\">⚠️ Hanya Dual Role (Step 1 + Step 2)</div>';
            }

            document.getElementById('stepButtonsList').innerHTML = stepBtnsHtml;
            subBar.classList.add('active');
        } else {
            subBar.classList.remove('active');
        }

        applyFilters();
    }

    function getStepSemanticLabel(stepNo, defaultLabel) {
        if (stepNo == 1) return '📝 Step 1: Input/Create (' + defaultLabel + ')';
        if (stepNo == 2) return '✅ Step 2: Approval (' + defaultLabel + ')';
        if (stepNo == 3) return '📦 Step 3: Packing/Prep (' + defaultLabel + ')';
        if (stepNo == 4) return '🚚 Step 4: Kirim/Delivery (' + defaultLabel + ')';
        if (stepNo == 5) return '🧾 Step 5: Penagihan/Invoice (' + defaultLabel + ')';
        return '🔹 Step ' + stepNo + ': ' + defaultLabel;
    }

    function selectWorkflowStep(stepNo) {
        currentStepFilter = stepNo;
        currentSoDFilter = false;
        document.getElementById('filterStepSelect').value = stepNo;

        var stepChips = document.querySelectorAll('#stepButtonsList .chip-btn');
        for (var i = 0; i < stepChips.length; i++) {
            var st = stepChips[i].getAttribute('data-step') || '';
            if (st === stepNo) {
                stepChips[i].classList.add('active-step');
            } else {
                stepChips[i].classList.remove('active-step');
            }
        }
        var chipSod = document.getElementById('chipSoD');
        if (chipSod) chipSod.classList.remove('active-sod');

        applyFilters();
    }

    function toggleSoDFilter() {
        currentSoDFilter = !currentSoDFilter;
        currentStepFilter = '';
        document.getElementById('filterStepSelect').value = '';

        var stepChips = document.querySelectorAll('#stepButtonsList .chip-btn');
        for (var i = 0; i < stepChips.length; i++) {
            stepChips[i].classList.remove('active-step');
        }
        var chipSod = document.getElementById('chipSoD');
        if (chipSod) {
            if (currentSoDFilter) chipSod.classList.add('active-sod');
            else chipSod.classList.remove('active-sod');
        }

        applyFilters();
    }

    function onMenuSelectChange() {
        var menuVal = document.getElementById('filterMenuSelect').value;
        selectWorkflowMenu(menuVal);
    }

    function onStepSelectChange() {
        var stepVal = document.getElementById('filterStepSelect').value;
        selectWorkflowStep(stepVal);
    }

    function applyFilters() {
        var searchVal = document.getElementById('filterSearch').value.toLowerCase().trim();
        var statusVal = document.getElementById('filterStatus').value;
        var moduleVal = document.getElementById('filterModule').value;
        var roleVal = currentRoleFilter;

        var rows = document.querySelectorAll('#empTable tbody tr.emp-row');
        var visibleCount = 0;
        var rowNum = 1;

        // Update Breadcrumb Alert
        var alertBar = document.getElementById('activeFilterBar');
        var breadcrumbText = document.getElementById('filterBreadcrumbText');
        var activeFilterDesc = [];

        if (currentMenuFilter !== '') {
            if (currentSoDFilter) {
                activeFilterDesc.push('Menu: <b>' + currentMenuFilter.toUpperCase() + '</b> (⚠️ Dual Role: Step 1 Input + Step 2 Approve)');
            } else if (currentStepFilter !== '') {
                activeFilterDesc.push('Menu: <b>' + currentMenuFilter.toUpperCase() + '</b> &rarr; <b>Step ' + currentStepFilter + '</b>');
            } else {
                activeFilterDesc.push('Menu: <b>' + currentMenuFilter.toUpperCase() + ' (Semua Step)</b>');
            }
        }
        if (roleVal !== '') {
            activeFilterDesc.push('Role: <b>' + (roleVal === '__EMPTY__' ? 'Tanpa Role' : roleVal) + '</b>');
        }
        if (moduleVal !== '') {
            activeFilterDesc.push('Modul: <b>' + moduleVal + '</b>');
        }

        if (activeFilterDesc.length > 0) {
            breadcrumbText.innerHTML = activeFilterDesc.join(' &bull; ');
            alertBar.classList.add('active');
        } else {
            alertBar.classList.remove('active');
        }

        for (var i = 0; i < rows.length; i++) {
            var row = rows[i];
            var idx = parseInt(row.getAttribute('data-idx'));
            var emp = employeesData[idx];

            var rSearch = row.getAttribute('data-search') || '';
            var rStatus = row.getAttribute('data-status') || '';
            var rRolesStr = row.getAttribute('data-roles') || '';
            var rRoles = rRolesStr ? rRolesStr.split(',') : [];
            var rModulesStr = row.getAttribute('data-modules') || '';
            var rModules = rModulesStr ? rModulesStr.split(',') : [];
            var rMenuCount = parseInt(row.getAttribute('data-menu-count') || '0');

            var matchSearch = (searchVal === '' || rSearch.indexOf(searchVal) !== -1);
            var matchStatus = (statusVal === '' || rStatus === statusVal);
            
            var matchRole = true;
            if (roleVal === '__EMPTY__') {
                matchRole = (rRoles.length === 0 || rRoles[0] === '');
            } else if (roleVal !== '') {
                matchRole = (rRoles.indexOf(roleVal) !== -1);
            }

            var matchModule = true;
            if (moduleVal === '__WITH_MENU__') {
                matchModule = (rMenuCount > 0);
            } else if (moduleVal === '__NO_MENU__') {
                matchModule = (rMenuCount === 0);
            } else if (moduleVal !== '') {
                matchModule = (rModules.indexOf(moduleVal) !== -1);
            }

            // Workflow Step Matcher
            var matchWorkflow = true;
            var empMenuSteps = (emp && emp.steps_map && emp.steps_map[currentMenuFilter]) ? emp.steps_map[currentMenuFilter] : null;

            if (currentMenuFilter !== '') {
                if (!empMenuSteps) {
                    matchWorkflow = false;
                } else {
                    if (currentSoDFilter) {
                        // Harus punya Step 1 DAN Step 2
                        matchWorkflow = (empMenuSteps['1'] && empMenuSteps['2']);
                    } else if (currentStepFilter !== '') {
                        // Harus punya step tertentu
                        matchWorkflow = !!empMenuSteps[currentStepFilter];
                    } else {
                        matchWorkflow = true;
                    }
                }
            }

            if (matchSearch && matchStatus && matchRole && matchModule && matchWorkflow) {
                row.style.display = '';
                var numCell = row.querySelector('.row-num');
                if (numCell) numCell.innerText = rowNum++;
                visibleCount++;

                // Highlight Workflow Step Pills on Row
                updateRowWorkflowHighlight(idx, currentMenuFilter, empMenuSteps);
            } else {
                row.style.display = 'none';
            }
        }

        document.getElementById('countShowing').innerText = visibleCount;
    }

    function updateRowWorkflowHighlight(idx, activeMenu, empMenuSteps) {
        var container = document.getElementById('wfSummary_' + idx);
        if (!container) return;

        if (activeMenu !== '' && empMenuSteps) {
            var stepKeys = Object.keys(empMenuSteps).sort();
            var html = '<div style=\"margin-bottom:3px;\"><strong style=\"color:#1e40af; font-size:11px;\">' + activeMenu.toUpperCase() + ' (' + stepKeys.length + ' Step Diizinkan):</strong></div>';
            
            var hasStep1 = false;
            var hasStep2 = false;

            for (var k = 0; k < stepKeys.length; k++) {
                var sNo = stepKeys[k];
                var sInfo = empMenuSteps[sNo];
                if (sNo == 1) hasStep1 = true;
                if (sNo == 2) hasStep2 = true;

                var pillClass = 'step-pill step-pill-' + (sNo <= 5 ? sNo : '1');
                html += '<span class=\"' + pillClass + '\">Step ' + sNo + ': ' + sInfo.label + ' (' + sInfo.code + ')</span>';
            }

            if (hasStep1 && hasStep2) {
                html += '<div style=\"margin-top:4px;\"><span class=\"step-pill step-pill-sod\">⚠️ Dual Role: Input (Step 1) + Approve (Step 2)</span></div>';
            }

            container.innerHTML = html;
        } else {
            // Restore default view
            var emp = employeesData[idx];
            if (!emp) return;
            var defaultHtml = '';
            if (emp.menu_total > 0) {
                defaultHtml += '<div style=\"margin-bottom:4px;\"><span class=\"badge-menu-count\">' + emp.menu_total + ' Menu Izin</span></div>';
                var showModCount = 0;
                for (var m = 0; m < emp.menu_modules.length; m++) {
                    defaultHtml += '<span class=\"badge-module\">' + emp.menu_modules[m] + '</span>';
                    showModCount++;
                    if (showModCount >= 3 && emp.menu_modules.length > 3) {
                        defaultHtml += '<span style=\"font-size:10px; color:#64748b;\">+' + (emp.menu_modules.length - 3) + ' lagi</span>';
                        break;
                    }
                }
            } else {
                defaultHtml = '<span class=\"role-pill-empty\">Belum ada izin di set_menu</span>';
            }
            container.innerHTML = defaultHtml;
        }
    }

    function filterByRoleChip(roleKey) {
        currentRoleFilter = roleKey;

        var chips = document.querySelectorAll('#roleCloudList .chip-btn');
        for (var i = 0; i < chips.length; i++) {
            var chip = chips[i];
            if (chip.getAttribute('data-role') === roleKey) {
                chip.classList.add('active');
            } else {
                chip.classList.remove('active');
            }
        }

        applyFilters();
    }

    function resetFilters() {
        document.getElementById('filterSearch').value = '';
        document.getElementById('filterStatus').value = '';
        document.getElementById('filterModule').value = '';
        currentRoleFilter = '';
        currentMenuFilter = '';
        currentStepFilter = '';
        currentSoDFilter = false;

        document.getElementById('filterMenuSelect').value = '';
        document.getElementById('filterStepSelect').value = '';
        document.getElementById('stepSubBar').classList.remove('active');

        // Reset chips
        var mChips = document.querySelectorAll('#menuWorkflowList .chip-btn');
        for (var i = 0; i < mChips.length; i++) {
            mChips[i].classList.remove('active');
        }
        var chipAll = document.getElementById('chipMenuAll');
        if (chipAll) chipAll.classList.add('active');

        var rChips = document.querySelectorAll('#roleCloudList .chip-btn');
        for (var j = 0; j < rChips.length; j++) {
            rChips[j].classList.remove('active');
            if (rChips[j].getAttribute('data-role') === '') rChips[j].classList.add('active');
        }

        applyFilters();
    }

    function switchModalTab(tabId) {
        var tabs = ['modalTabMenu', 'modalTabRole', 'modalTabRaw'];
        var btns = { 'modalTabMenu': 'btnTabMenu', 'modalTabRole': 'btnTabRole', 'modalTabRaw': 'btnTabRaw' };
        for (var t = 0; t < tabs.length; t++) {
            var el = document.getElementById(tabs[t]);
            var btn = document.getElementById(btns[tabs[t]]);
            if (tabs[t] === tabId) {
                if (el) el.classList.add('active');
                if (btn) btn.classList.add('active');
            } else {
                if (el) el.classList.remove('active');
                if (btn) btn.classList.remove('active');
            }
        }
    }

    function showEmployeeDetail(idx) {
        var emp = employeesData[idx];
        if (!emp) return;
        currentModalEmployee = emp;

        document.getElementById('modalTitle').innerText = emp.nama + ' (#' + emp.id + ')';
        document.getElementById('modalSubtitle').innerText = '@' + emp.nama_login + ' • ' + (emp.cabang_nama || 'Tanpa Cabang') + ' • ' + emp.employee_type;

        var gridHtml = '';
        gridHtml += '<div class=\"detail-item\"><div class=\"detail-label\">ID / Username</div><div class=\"detail-val\">#' + emp.id + ' (@' + emp.nama_login + ')</div></div>';
        gridHtml += '<div class=\"detail-item\"><div class=\"detail-label\">Nama Lengkap</div><div class=\"detail-val\">' + emp.nama + '</div></div>';
        gridHtml += '<div class=\"detail-item\"><div class=\"detail-label\">Tipe Karyawan</div><div class=\"detail-val\"><span class=\"badge badge-type\">' + emp.employee_type + '</span></div></div>';
        gridHtml += '<div class=\"detail-item\"><div class=\"detail-label\">Jenis (Legacy)</div><div class=\"detail-val\">' + (emp.jenis || '-') + '</div></div>';
        gridHtml += '<div class=\"detail-item\"><div class=\"detail-label\">Cabang</div><div class=\"detail-val\">' + (emp.cabang_nama || '-') + ' (ID: ' + emp.cabang_id + ')</div></div>';
        gridHtml += '<div class=\"detail-item\"><div class=\"detail-label\">Divisi</div><div class=\"detail-val\">' + (emp.div_name || '-') + ' (ID: ' + emp.div_id + ')</div></div>';
        gridHtml += '<div class=\"detail-item\"><div class=\"detail-label\">Status Akun</div><div class=\"detail-val\">' + (emp.trash === 1 ? '🔴 Terhapus (trash=1)' : (emp.status === 1 ? '🟢 Aktif (status=1)' : '🟡 Nonaktif (status=0)')) + '</div></div>';
        gridHtml += '<div class=\"detail-item\"><div class=\"detail-label\">Sesi Login</div><div class=\"detail-val\">' + (emp.status_login === 1 ? '🟢 Online' : '⚪ Offline') + '</div></div>';
        gridHtml += '<div class=\"detail-item\"><div class=\"detail-label\">Aktivitas Terakhir</div><div class=\"detail-val\">' + (emp.last_dtime_active || emp.last_dtime || '-') + '</div></div>';
        gridHtml += '<div class=\"detail-item\"><div class=\"detail-label\">Total Izin Menu</div><div class=\"detail-val\"><span class=\"badge-menu-count\">' + emp.menu_total + ' Menu Izin</span> (' + emp.menu_modules.length + ' Modul)</div></div>';

        document.getElementById('modalGrid').innerHTML = gridHtml;
        document.getElementById('modalRoleCountBadge').innerText = emp.roles.length;
        document.getElementById('modalMenuCountBadge').innerText = emp.menu_total;

        // Render Roles Table
        var roleTableHtml = '';
        if (emp.roles.length > 0) {
            roleTableHtml += '<table class=\"modal-role-table\">';
            roleTableHtml += '<thead><tr><th style=\"width:40px;\">No</th><th style=\"width:180px;\">Kode Role</th><th style=\"width:160px;\">Scope / Kategori</th><th>Deskripsi</th></tr></thead><tbody>';
            for (var r = 0; r < emp.roles.length; r++) {
                var roleCode = emp.roles[r];
                var scopeInfo = getRoleScope(roleCode);
                var desc = roleDescriptions[roleCode] || '-';
                roleTableHtml += '<tr>';
                roleTableHtml += '<td style=\"text-align:center;\">' + (r + 1) + '</td>';
                roleTableHtml += '<td><strong>' + roleCode + '</strong></td>';
                roleTableHtml += '<td><span class=\"role-pill\" style=\"background:' + scopeInfo.color + '\">' + scopeInfo.name + '</span></td>';
                roleTableHtml += '<td>' + desc + '</td>';
                roleTableHtml += '</tr>';
            }
            roleTableHtml += '</tbody></table>';
        } else {
            roleTableHtml = '<div style=\"padding:15px; background:#f8fafc; border:1px dashed #cbd5e1; border-radius:6px; color:#94a3b8; text-align:center;\">Karyawan ini tidak memiliki role membership.</div>';
        }
        document.getElementById('modalRolesTableContainer').innerHTML = roleTableHtml;

        // Render Menu Items
        renderModalMenuTable(emp.menus);

        // Render Modules Summary in Modal
        var modSumHtml = '';
        for (var m = 0; m < emp.menu_modules.length; m++) {
            modSumHtml += '<span class=\"badge-module\">' + emp.menu_modules[m] + '</span>';
        }
        document.getElementById('modalModulesSummary').innerHTML = modSumHtml;

        document.getElementById('modalRawBox').innerText = JSON.stringify(emp.roles, null, 2);
        document.getElementById('modalMenuRawBox').innerText = JSON.stringify(emp.menus, null, 2);

        // Switch to Menu Tab by default if has menus, else role
        if (emp.menu_total > 0) {
            switchModalTab('modalTabMenu');
        } else {
            switchModalTab('modalTabRole');
        }

        document.getElementById('detailModal').style.display = 'flex';
    }

    function renderModalMenuTable(items) {
        var container = document.getElementById('modalMenuTableContainer');
        if (!items || items.length === 0) {
            container.innerHTML = '<div style=\"padding:20px; background:#f8fafc; border:1px dashed #cbd5e1; border-radius:6px; color:#94a3b8; text-align:center;\">Belum ada izin menu yang dikonfigurasi di tabel set_menu untuk karyawan ini.</div>';
            return;
        }

        var html = '<table class=\"modal-role-table\" id=\"modalMenuTable\">';
        html += '<thead><tr><th style=\"width:40px;\">No</th><th style=\"width:160px;\">Modul / Grup</th><th>Nama Menu &amp; Fitur</th><th style=\"width:180px;\">Tahapan / Step Workflow</th><th style=\"width:100px; text-align:center;\">Scope Cabang</th></tr></thead><tbody>';
        for (var i = 0; i < items.length; i++) {
            var it = items[i];
            var cabLabel = (it.cabang_id === -1 || it.cabang_id === '-1') ? 'Semua Cabang' : 'Cabang ' + it.cabang_id;
            var pillClass = 'step-pill step-pill-' + (it.step_no <= 5 ? it.step_no : '1');

            html += '<tr class=\"modal-menu-row\" data-text=\"' + (it.group + ' ' + it.menu + ' ' + it.step_label + ' ' + it.step_code).toLowerCase() + '\">';
            html += '<td style=\"text-align:center;\">' + (i + 1) + '</td>';
            html += '<td><span class=\"badge-module\">' + it.group + '</span></td>';
            html += '<td><strong>' + it.menu + '</strong></td>';
            html += '<td><span class=\"' + pillClass + '\">Step ' + it.step_no + ': ' + it.step_label + ' (' + it.step_code + ')</span></td>';
            html += '<td style=\"text-align:center; font-size:11px; color:#475569;\">' + cabLabel + '</td>';
            html += '</tr>';
        }
        html += '</tbody></table>';
        container.innerHTML = html;
    }

    function filterModalMenuItems() {
        var q = document.getElementById('searchModalMenu').value.toLowerCase().trim();
        var rows = document.querySelectorAll('#modalMenuTable tbody tr.modal-menu-row');
        for (var i = 0; i < rows.length; i++) {
            var txt = rows[i].getAttribute('data-text') || '';
            if (q === '' || txt.indexOf(q) !== -1) {
                rows[i].style.display = '';
            } else {
                rows[i].style.display = 'none';
            }
        }
    }

    function closeModal() {
        document.getElementById('detailModal').style.display = 'none';
        currentModalEmployee = null;
    }

    function handleModalOverlayClick(e) {
        if (e.target && e.target.id === 'detailModal') {
            closeModal();
        }
    }

    document.addEventListener('keydown', function(e) {
        if (e.key === 'Escape') {
            closeModal();
        }
    });

    function exportToCSV() {
        var rows = document.querySelectorAll('#empTable tbody tr.emp-row');
        var csv = [];
        csv.push(['No', 'ID', 'Nama', 'Username', 'Jenis', 'Tipe Karyawan', 'Cabang', 'Status', 'Total Role', 'Daftar Role', 'Total Menu Izin', 'Daftar Modul Menu', 'Tahapan Menu Terfilter'].join(';'));

        var counter = 1;
        for (var i = 0; i < rows.length; i++) {
            var row = rows[i];
            if (row.style.display !== 'none') {
                var idx = parseInt(row.getAttribute('data-idx'));
                var emp = employeesData[idx];
                if (emp) {
                    var statusStr = emp.trash === 1 ? 'Trash' : (emp.status === 1 ? 'Aktif' : 'Nonaktif');
                    var activeStepDesc = '';
                    if (currentMenuFilter !== '' && emp.steps_map && emp.steps_map[currentMenuFilter]) {
                        var stKeys = Object.keys(emp.steps_map[currentMenuFilter]);
                        activeStepDesc = currentMenuFilter + ' (Steps: ' + stKeys.join(', ') + ')';
                    }
                    var line = [
                        counter++,
                        emp.id,
                        '\"' + (emp.nama || '').replace(/\"/g, '\"\"') + '\"',
                        '\"' + (emp.nama_login || '').replace(/\"/g, '\"\"') + '\"',
                        '\"' + (emp.jenis || '').replace(/\"/g, '\"\"') + '\"',
                        '\"' + (emp.employee_type || '').replace(/\"/g, '\"\"') + '\"',
                        '\"' + (emp.cabang_nama || '').replace(/\"/g, '\"\"') + '\"',
                        statusStr,
                        emp.roles.length,
                        '\"' + (emp.roles.join(', ')).replace(/\"/g, '\"\"') + '\"',
                        emp.menu_total,
                        '\"' + (emp.menu_modules.join(', ')).replace(/\"/g, '\"\"') + '\"',
                        '\"' + activeStepDesc.replace(/\"/g, '\"\"') + '\"'
                    ];
                    csv.push(line.join(';'));
                }
            }
        }

        var csvContent = '\uFEFF' + csv.join('\\n');
        var blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
        var url = URL.createObjectURL(blob);
        var link = document.createElement('a');
        link.setAttribute('href', url);
        link.setAttribute('download', 'monitoring_workflow_steps_' + new Date().toISOString().slice(0,10) + '.csv');
        document.body.appendChild(link);
        link.click();
        document.body.removeChild(link);
    }

    // Initial filter run
    applyFilters();
</script>

</body>
</html>";
    }
