    // START OF COMPLETE REPEATED LOGIC
    public function dataObservabilityGovernance()
    {
        // Handle AJAX Webhook & Remediation Test Trigger
        $action = isset($_GET['action']) ? $_GET['action'] : (isset($_POST['action']) ? $_POST['action'] : '');
        if ($action === 'test_webhook') {
            $webhookUrl = isset($_POST['webhook_url']) ? trim($_POST['webhook_url']) : '';
            $payloadJson = isset($_POST['payload']) ? $_POST['payload'] : '';

            $response = array(
                'status' => 'error',
                'message' => 'URL Webhook tidak boleh kosong.',
                'timestamp' => date('Y-m-d H:i:s')
            );

            if ($webhookUrl !== '') {
                $ch = curl_init($webhookUrl);
                curl_setopt($ch, CURLOPT_CUSTOMREQUEST, "POST");
                curl_setopt($ch, CURLOPT_POSTFIELDS, $payloadJson);
                curl_setopt($ch, CURLOPT_RETURNTRANSFER, true);
                curl_setopt($ch, CURLOPT_HTTPHEADER, array(
                    'Content-Type: application/json',
                    'Content-Length: ' . strlen($payloadJson)
                ));
                curl_setopt($ch, CURLOPT_TIMEOUT, 5);
                curl_setopt($ch, CURLOPT_SSL_VERIFYPEER, false);

                $result = curl_exec($ch);
                $httpCode = curl_getinfo($ch, CURLINFO_HTTP_CODE);
                $curlError = curl_error($ch);
                curl_close($ch);

                if ($curlError) {
                    $response['message'] = "Gagal mengirim webhook: " . $curlError;
                } else {
                    $response['status'] = 'success';
                    $response['http_code'] = $httpCode;
                    $response['message'] = "Webhook terkirim! Respons HTTP: " . $httpCode . " - " . substr($result, 0, 100);
                }
            }

            header('Content-Type: application/json');
            echo json_encode($response);
            return;
        }

        $auditStartTime = microtime(true);
