        // -------------------------------------------------------------
        // PART 1 - CHECK 8 (Tier 3.B - Statistical): Volume Drift Detection
        // -------------------------------------------------------------
        $sql8 = "SELECT DATE(dtime) as tgl, count(*) as cnt 
                 FROM (
                     SELECT id, dtime 
                     FROM transaksi 
                     ORDER BY id DESC 
                     LIMIT 20000
                 ) t 
                 GROUP BY DATE(dtime) 
                 ORDER BY tgl DESC 
                 LIMIT 14";
        $res8 = $this->db->query($sql8);
        $dailyCounts = array();
        if ($res8) {
            $rows8 = $res8->result_array();
            foreach ($rows8 as $r) {
                $dailyCounts[$r['tgl']] = (int)$r['cnt'];
            }
        }
        $n = count($dailyCounts);
        $mean = $n > 0 ? array_sum($dailyCounts) / $n : 0;
        $variance = 0;
        foreach ($dailyCounts as $c) {
            $variance += pow($c - $mean, 2);
        }
        $stdDev = $n > 1 ? sqrt($variance / ($n - 1)) : 0;
        $latestDate = '';
        $latestCount = 0;
        foreach ($dailyCounts as $d => $c) {
            $latestDate = $d;
            $latestCount = $c;
            break;
        }
        $driftSigma = ($stdDev > 0) ? round(abs($latestCount - $mean) / $stdDev, 2) : 0;
        $isVolumeAnomaly = ($driftSigma >= 2.0);

        $samples8 = array();
        foreach ($dailyCounts as $d => $c) {
            $diffFromMean = $c - $mean;
            $samples8[] = array(
                'identifier' => 'Tanggal: ' . $d,
                'volume' => number_format($c) . ' Transaksi',
                'deviasi' => ($diffFromMean >= 0 ? '+' : '') . number_format($diffFromMean, 1),
                'z_score' => ($stdDev > 0 ? number_format(($c - $mean) / $stdDev, 2) . 'σ' : '0σ'),
                'keterangan' => (abs($c - $mean) >= 2 * $stdDev ? 'Anomali Volume Drift (> 2σ)' : 'Normal')
            );
        }

