            'count' => ($isVolumeAnomaly ? 1 : 0),
            'summary' => 'Rata-rata 14 hari: ' . number_format($mean, 1) . ' trx/hari (StdDev: ' . number_format($stdDev, 1) . '). Terkini (' . $latestDate . '): ' . number_format($latestCount) . ' trx (Z-Score: ' . $driftSigma . 'σ).',
