            SUM(CASE WHEN dtime >= DATE_SUB(NOW(), INTERVAL 365 DAY) AND dtime < DATE_SUB(NOW(), INTERVAL 90 DAY) THEN 1 ELSE 0 END) AS warm_rows,
            SUM(CASE WHEN dtime < DATE_SUB(NOW(), INTERVAL 365 DAY) THEN 1 ELSE 0 END) AS cold_rows,
            COUNT(*) as total_rows
        FROM jurnal WHERE trash = 0";
        $resJT = $this->db->query($sqlJurnalTiers);
        $rowsJT = $resJT ? $resJT->result_array() : array();
        $tierRow = isset($rowsJT[0]) ? $rowsJT[0] : array();
        $hotRows = isset($tierRow['hot_rows']) ? (int)$tierRow['hot_rows'] : 0;
        $warmRows = isset($tierRow['warm_rows']) ? (int)$tierRow['warm_rows'] : 0;
        $coldRows = isset($tierRow['cold_rows']) ? (int)$tierRow['cold_rows'] : 0;
        $totalLedgerRows = isset($tierRow['total_rows']) ? (int)$tierRow['total_rows'] : ($hotRows + $warmRows + $coldRows);
        if ($totalLedgerRows === 0) $totalLedgerRows = 1;

        $pctHot = round(($hotRows / $totalLedgerRows) * 100, 1);
        $pctWarm = round(($warmRows / $totalLedgerRows) * 100, 1);
        $pctCold = round(($coldRows / $totalLedgerRows) * 100, 1);

