        .suite-title p { font-size: 12px; color: #64748b; margin-top: 4px; }
        .suite-actions { display: flex; gap: 10px; align-items: center; }

        /* Buttons */
        .btn {
            display: inline-flex;
            align-items: center;
            gap: 6px;
            padding: 8px 15px;
            border-radius: 6px;
