        .lineage-node.node-slate { border-top-color: #0f172a; }
        .lineage-node h4 { font-size: 12px; font-weight: 800; color: #0f172a; margin-bottom: 6px; }
        .lineage-node p { font-size: 11px; color: #64748b; margin-bottom: 8px; line-height: 1.4; }
        .lineage-meta { font-family: monospace; font-size: 10px; background: #e2e8f0; padding: 4px 6px; border-radius: 4px; color: #1e293b; }
        .lineage-arrow { font-size: 20px; color: #94a3b8; font-weight: 800; }

        /* Reconciliation Cards */
        .recon-grid {
            display: grid;
            grid-template-columns: repeat(auto-fit, minmax(320px, 1fr));
