        }
        .recon-card h4 { font-size: 13px; font-weight: 700; color: #0f172a; margin-bottom: 12px; display: flex; justify-content: space-between; align-items: center; }
        .recon-item { display: flex; justify-content: space-between; font-size: 12px; margin-bottom: 6px; padding: 4px 0; border-bottom: 1px dashed #e2e8f0; }
        .recon-item span.lbl { color: #64748b; }
        .recon-item span.val { font-weight: 700; color: #0f172a; }
        .recon-delta { display: flex; justify-content: space-between; font-size: 12px; margin-top: 8px; padding-top: 6px; font-weight: 800; }

        /* FinOps Tier Bar */
        .finops-tier-bar {
            display: flex;
            height: 28px;
