        /* Part 3: Digital Twin Simulation Sliders */
        .twin-slider-group {
            display: grid;
            grid-template-columns: repeat(auto-fit, minmax(300px, 1fr));
            gap: 20px;
            margin-bottom: 24px;
        }
        .twin-slider-card {
            background: #f8fafc;
            border: 1px solid #cbd5e1;
            border-radius: 8px;
            padding: 18px;
        }
        .twin-slider-card label {
            display: flex;
            justify-content: space-between;
            font-weight: 700;
            font-size: 13px;
            margin-bottom: 10px;
            color: #0f172a;
        }
        .twin-slider-card input[type=range] {
            width: 100%;
            height: 6px;
            border-radius: 3px;
            background: #cbd5e1;
            outline: none;
            cursor: pointer;
        }

        /* Modal Drilldown */
        .modal-backdrop {
            display: none;
            position: fixed;
            top: 0; left: 0; width: 100%; height: 100%;
            background: rgba(15, 23, 42, 0.6);
            z-index: 9999;
            align-items: center;
            justify-content: center;
        }
        .modal-content {
            background: #fff;
            border-radius: 12px;
            max-width: 850px;
            width: 90%;
            max-height: 85vh;
            overflow-y: auto;
            padding: 24px;
            box-shadow: 0 20px 25px -5px rgba(0, 0, 0, 0.1);
        }
        .modal-header {
            display: flex;
            justify-content: space-between;
            align-items: center;
            border-bottom: 1px solid #e2e8f0;
            padding-bottom: 14px;
            margin-bottom: 16px;
        }
        .modal-header h3 { font-size: 16px; font-weight: 800; color: #0f172a; }
        .modal-close { font-size: 22px; cursor: pointer; color: #64748b; font-weight: bold; }

        @media print {
            body { background: #fff; padding: 0; font-size: 10px; }
            .suite-actions, .main-nav, .filter-toolbar, .btn, .twin-slider-group { display: none !important; }
            .tab-panel { display: block !important; margin-bottom: 30px; }
            .report-card { border: none; box-shadow: none; padding: 0; margin-bottom: 20px; }
            table.obs-table th { background: #eee !important; color: #000 !important; }
        }
    </style>
    <script>
        window.switchMainTab = function(tabId) {
            var tabs = document.querySelectorAll('.main-tab');
            var panels = document.querySelectorAll('.tab-panel');

            for (var i = 0; i < panels.length; i++) {
                panels[i].classList.remove('active');
            }
            for (var j = 0; j < tabs.length; j++) {
                tabs[j].classList.remove('active');
                var oc = tabs[j].getAttribute('onclick') || '';
                if (oc.indexOf(tabId) !== -1) {
                    tabs[j].classList.add('active');
                }
            }

            var target = document.getElementById(tabId);
            if (target) target.classList.add('active');
        };

        window.switchViewerRole = function(role) {
            var maskedElements = document.querySelectorAll('.pii-masked');
            var unmaskedElements = document.querySelectorAll('.pii-unmasked');
            var roleBadge = document.getElementById('active-role-badge');

            if (role === 'privileged') {
                for (var i = 0; i < maskedElements.length; i++) maskedElements[i].style.display = 'none';
                for (var j = 0; j < unmaskedElements.length; j++) unmaskedElements[j].style.display = 'inline';
                if (roleBadge) {
                    roleBadge.className = 'badge badge-green';
                    roleBadge.innerText = 'C-Level / Data Governor (Unmasked)';
                }
            } else {
                for (var i = 0; i < maskedElements.length; i++) maskedElements[i].style.display = 'inline';
                for (var j = 0; j < unmaskedElements.length; j++) unmaskedElements[j].style.display = 'none';
                if (roleBadge) {
                    roleBadge.className = 'badge badge-slate';
                    roleBadge.innerText = 'Data Analyst / External (Masked)';
                }
            }
        };

        var currentRulesData = " . $rulesJson . ";

        window.filterDomain = function(domain, btn) {
            var buttons = document.querySelectorAll('.filter-btn');
            for (var i = 0; i < buttons.length; i++) buttons[i].classList.remove('active');
            if (btn) btn.classList.add('active');

            var rows = document.querySelectorAll('#rules-tbody tr');
            for (var j = 0; j < rows.length; j++) {
                var rowDomain = rows[j].getAttribute('data-domain');
                if (domain === 'ALL' || rowDomain === domain) {
                    rows[j].style.display = '';
                } else {
                    rows[j].style.display = 'none';
                }
            }
        };

        window.searchRules = function() {
            var q = (document.getElementById('rule-search').value || '').toLowerCase();
            var rows = document.querySelectorAll('#rules-tbody tr');
            for (var i = 0; i < rows.length; i++) {
                var text = rows[i].innerText.toLowerCase();
                rows[i].style.display = (text.indexOf(q) !== -1) ? '' : 'none';
            }
        };

        window.openAuditModal = function(ruleId) {
            var found = null;
            for (var i = 0; i < currentRulesData.length; i++) {
                if (currentRulesData[i].id === ruleId) {
                    found = currentRulesData[i];
                    break;
                }
            }
            if (!found) return;

            document.getElementById('modal-title').innerText = '[' + found.id + '] ' + found.name;
            document.getElementById('modal-summary').innerText = found.summary;
            document.getElementById('modal-action').innerText = found.action;

            var tbody = document.getElementById('modal-tbody');
            tbody.innerHTML = '';

            if (found.samples && found.samples.length > 0) {
                for (var s = 0; s < found.samples.length; s++) {
                    var sample = found.samples[s];
                    var tr = document.createElement('tr');
                    var keys = Object.keys(sample);
                    for (var k = 0; k < keys.length; k++) {
                        var td = document.createElement('td');
                        td.innerText = sample[keys[k]];
                        tr.appendChild(td);
                    }
                    tbody.appendChild(tr);
                }
            } else {
                var tr = document.createElement('tr');
                var td = document.createElement('td');
                td.colSpan = 5;
                td.style.textAlign = 'center';
                td.style.padding = '20px';
                td.innerText = 'Tidak ada anomali atau data bersih (Clean Gate).';
                tr.appendChild(td);
                tbody.appendChild(tr);
            }

            document.getElementById('audit-modal').style.display = 'flex';
        };

        window.closeAuditModal = function() {
            document.getElementById('audit-modal').style.display = 'none';
        };

        window.sendWebhookTest = function() {
            var url = document.getElementById('webhook-url').value;
            var statusBox = document.getElementById('webhook-response');
            if (!url) {
                alert('Silakan masukkan URL Webhook terlebih dahulu.');
                return;
            }

            statusBox.innerText = 'Mengirim payload ke webhook...';

            var payload = {
                title: 'Enterprise Data Observability Alert',
                system: 'Everest ERP Production',
                health_score: '" . $healthScore . "%',
                health_status: '" . $healthStatusText . "',
                timestamp: new Date().toISOString(),
                violations: []
            };

            for (var i = 0; i < currentRulesData.length; i++) {
                if (currentRulesData[i].status === 'VIOLATION') {
                    payload.violations.push({
                        rule_id: currentRulesData[i].id,
                        rule_name: currentRulesData[i].name,
                        domain: currentRulesData[i].domain,
                        severity: currentRulesData[i].severity,
                        affected_count: currentRulesData[i].count,
                        summary: currentRulesData[i].summary
                    });
                }
            }

            var xhr = new XMLHttpRequest();
            xhr.open('POST', window.location.href.split('?')[0] + '?action=test_webhook', true);
            xhr.setRequestHeader('Content-Type', 'application/x-www-form-urlencoded');
            xhr.onreadystatechange = function() {
                if (xhr.readyState === 4) {
                    try {
                        var res = JSON.parse(xhr.responseText);
                        statusBox.innerText = '[' + res.status.toUpperCase() + '] ' + res.message;
                    } catch(e) {
                        statusBox.innerText = 'Respons Server: ' + xhr.responseText;
                    }
                }
            };
            xhr.send('webhook_url=' + encodeURIComponent(url) + '&payload=' + encodeURIComponent(JSON.stringify(payload, null, 2)));
        };

        window.exportTableToCSV = function(tableId, filename) {
            var table = document.getElementById(tableId);
            if (!table) {
                alert('Tabel tidak ditemukan.');
                return;
            }

            var csv = [];
            var rows = table.querySelectorAll('tr');
            for (var i = 0; i < rows.length; i++) {
                var row = [];
                var cols = rows[i].querySelectorAll('td, th');
                for (var j = 0; j < cols.length; j++) {
                    var text = (cols[j].innerText || '').replace(/\\s+/g, ' ').replace(/\"/g, '\"\"').trim();
                    row.push('\"' + text + '\"');
                }
                if (row.length > 0) csv.push(row.join(';'));
            }

            var csvContent = '\\uFEFF' + csv.join('\\n');
            var blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
            var url = URL.createObjectURL(blob);
            var a = document.createElement('a');
            a.href = url;
            a.download = filename + '_' + new Date().toISOString().slice(0,10) + '.csv';
            document.body.appendChild(a);
            a.click();
            document.body.removeChild(a);
        };

        // Part 3 JS: Cryptographic Verification Simulator
        window.verifyCryptoLedger = function() {
            var badge = document.getElementById('crypto-status-badge');
            var log = document.getElementById('crypto-verify-log');
            log.innerText = 'Menghitung ulang hash SHA-256 seluruh blok rantai mutasi jurnal...';
            setTimeout(function() {
                badge.className = 'badge badge-green';
                badge.innerText = '100% IMMUTABLE & VERIFIED';
                log.innerText = '[VERIFIED] Seluruh 8 blok mutasi berurutan lolos audit validasi hash SHA-256. Zero tampering / integritas mutlak terbukti.';
            }, 600);
        };

        // Part 3 JS: Self-Healing Trigger Simulator
        window.triggerRemediation = function(actionId) {
            var log = document.getElementById('remediation-log');
            log.innerText = 'Mengeksekusi pipeline remediasi ' + actionId + '...';
            setTimeout(function() {
                if (actionId === 'SH-001') {
                    log.innerText = '[SUCCESS] Pipeline SH-001 dieksekusi: 10,662 entri kunci transaksi gantung pada dokumen batal berhasil dibersihkan via normalisasiStok(true).';
                } else if (actionId === 'SH-002') {
                    log.innerText = '[SUCCESS] Pipeline SH-002 dieksekusi: Anti-collision daemon aktif pada gateway transaksi. Zero collision terdeteksi.';
                } else {
                    log.innerText = '[SUCCESS] Pipeline SH-003 dieksekusi: Draf jurnal balancing adjustment otomatis dibentuk dan siap diposting ke GL.';
                }
            }, 700);
        };

        // Part 3 JS: Reverse ETL Sync Trigger Simulator
        window.triggerReverseEtl = function(pipelineName) {
            var log = document.getElementById('retl-log');
            log.innerText = 'Mendorong intelijen analitik dari ' + pipelineName + ' ke modul operasional...';
            setTimeout(function() {
                log.innerText = '[SYNC SUCCESS] ' + pipelineName + ' berhasil diinjeksikan ke modul operasional. Staf lapangan akan menerima notifikasi real-time.';
            }, 600);
        };

        // Part 3 JS: Digital Twin What-If Recalculation
        var baseRev = " . $baseRev . ";
        var baseHpp = " . $baseHpp . ";
        var baseOpex = " . $baseOpex . ";
        var baseCash = " . $baseCash . ";

        window.updateDigitalTwin = function() {
            var pDelta = parseFloat(document.getElementById('sim-price').value);
            var oDelta = parseFloat(document.getElementById('sim-opex').value);
            var vDelta = parseFloat(document.getElementById('sim-vol').value);

            document.getElementById('val-sim-price').innerText = (pDelta >= 0 ? '+' : '') + pDelta + '%';
            document.getElementById('val-sim-opex').innerText = (oDelta >= 0 ? '+' : '') + oDelta + '%';
            document.getElementById('val-sim-vol').innerText = (vDelta >= 0 ? '+' : '') + vDelta + '%';

            var simRev = baseRev * (1 + pDelta / 100) * (1 + vDelta / 100);
            var simHpp = baseHpp * (1 + vDelta / 100);
            var simOpex = baseOpex * (1 + oDelta / 100);
            var simProfit = simRev - simHpp - simOpex;
            var simTax = (simProfit > 0) ? simProfit * 0.22 : 0;
            var simCash = baseCash + (simProfit - simTax);
            var runway = (simOpex > 0) ? (baseCash / (simOpex / 12)).toFixed(1) : '∞';

            document.getElementById('twin-res-rev').innerText = 'Rp ' + (simRev / 1000000000).toFixed(2) + ' M';
            document.getElementById('twin-res-profit').innerText = 'Rp ' + (simProfit / 1000000000).toFixed(2) + ' M';
            document.getElementById('twin-res-tax').innerText = 'Rp ' + (simTax / 1000000000).toFixed(2) + ' M';
            document.getElementById('twin-res-runway').innerText = runway + ' Bulan';
        };
    </script>
</head>
