    // START OF COMPLETE REPEATED LOGIC
    public function corporateFinancialReports()
    {
        // 1. Ambil agregasi data akuntansi dari tabel jurnal
        $sql = "SELECT LEFT(rekening, 1) as coa_type, 
                       LEFT(rekening, 6) as coa_sub,
                       rekening,
                       MAX(rekening_main) as rek_name,
                       SUM(debet) as tot_debet, 
                       SUM(kredit) as tot_kredit 
                FROM jurnal 
                WHERE trash = 0 AND rekening IS NOT NULL AND rekening != '' 
                GROUP BY LEFT(rekening, 1), LEFT(rekening, 6), rekening";
        $res = $this->db->query($sql);
        $rows = array();
        if ($res) {
            $rows = $res->result_array();
        }

        // 2. Olah data ke dalam 7 kategori standar COA
        $assets = array();
        $liabilities = array();
        $equities = array();
        $revenues = array();
        $cogs = array();
        $expenses = array();
        $others = array();

        $totAsset = 0;
        $totKasBank = 0;
        $totPiutang = 0;
        $totPersediaan = 0;
        $totAsetTetap = 0;
        $bankAccounts = array();

        $totLiability = 0;
        $totHutangUsaha = 0;
        $totHutangPajak = 0;
        $totHutangBank = 0;

        $totEquity = 0;
        $totRevenue = 0;
        $totHpp = 0;
        $totOpex = 0;
        $totOther = 0;

        foreach ($rows as $r) {
            $type = $r['coa_type'];
            $sub = $r['coa_sub'];
            $rek = $r['rekening'];
            $name = (string)$r['rek_name'];
            if ($name === '') {
                $name = 'Akun ' . $rek;
            }

            $d = (float)$r['tot_debet'];
            $k = (float)$r['tot_kredit'];

            if ($type === '1') {
                // Aset: Saldo normal Debet
                $saldo = $d - $k;
                $totAsset += $saldo;
                $item = array('rekening' => $rek, 'nama' => $name, 'saldo' => $saldo);
                $assets[] = $item;

                if (strpos($rek, '101001') === 0) {
                    $totKasBank += $saldo;
                    $bankAccounts[] = $item;
                } elseif (strpos($rek, '101002') === 0) {
                    $totPiutang += $saldo;
                } elseif (strpos($rek, '101003') === 0) {
                    $totPersediaan += $saldo;
                } elseif (strpos($rek, '1020') === 0) {
                    $totAsetTetap += $saldo;
                }
            } elseif ($type === '2') {
                // Kewajiban: Saldo normal Kredit
                $saldo = $k - $d;
                $totLiability += $saldo;
                $item = array('rekening' => $rek, 'nama' => $name, 'saldo' => $saldo);
                $liabilities[] = $item;

                if (strpos($rek, '2010') === 0) {
                    $totHutangUsaha += $saldo;
                } elseif (strpos($rek, '2030') === 0) {
                    $totHutangPajak += $saldo;
                } else {
                    $totHutangBank += $saldo;
                }
            } elseif ($type === '3') {
                // Ekuitas: Saldo normal Kredit
                $saldo = $k - $d;
                $totEquity += $saldo;
                $equities[] = array('rekening' => $rek, 'nama' => $name, 'saldo' => $saldo);
            } elseif ($type === '4') {
                // Pendapatan: Saldo normal Kredit
                $saldo = $k - $d;
                $totRevenue += $saldo;
                $revenues[] = array('rekening' => $rek, 'nama' => $name, 'saldo' => $saldo);
            } elseif ($type === '5') {
                // HPP: Saldo normal Debet
                $saldo = $d - $k;
                $totHpp += $saldo;
                $cogs[] = array('rekening' => $rek, 'nama' => $name, 'saldo' => $saldo);
            } elseif ($type === '6') {
                // Beban Operasional: Saldo normal Debet
                $saldo = $d - $k;
                $totOpex += $saldo;
                $expenses[] = array('rekening' => $rek, 'nama' => $name, 'saldo' => $saldo);
            } elseif ($type === '7') {
                // Pendapatan / Beban Lain-Lain: Net Kredit - Debet
                $saldo = $k - $d;
                $totOther += $saldo;
                $others[] = array('rekening' => $rek, 'nama' => $name, 'saldo' => $saldo);
            }
        }

        // Kalkulasi Laba Rugi Pokok
        $grossProfit = $totRevenue - $totHpp;
        $gpm = $totRevenue > 0 ? ($grossProfit / $totRevenue) * 100 : 0;

        $operatingIncome = $grossProfit - $totOpex;
        $operatingMargin = $totRevenue > 0 ? ($operatingIncome / $totRevenue) * 100 : 0;

        $ebt = $operatingIncome + $totOther;
        $citRate = 0.22; // Tarif PPh Badan 22%
        $taxExpense = $ebt > 0 ? ($ebt * $citRate) : 0;
        $netIncome = $ebt - $taxExpense;
        $npm = $totRevenue > 0 ? ($netIncome / $totRevenue) * 100 : 0;

        // Total Ekuitas Akhir
        $totEquityFinal = $totEquity + $netIncome;

        // Rasio Likuiditas & Solvabilitas
        $currentAssets = $totKasBank + $totPiutang + $totPersediaan;
        $currentLiabilities = $totHutangUsaha + $totHutangPajak;
        $currentRatio = $currentLiabilities > 0 ? ($currentAssets / $currentLiabilities) : 0;
        $quickRatio = $currentLiabilities > 0 ? (($totKasBank + $totPiutang) / $currentLiabilities) : 0;

        $debtToAssetRatio = $totAsset > 0 ? ($totLiability / $totAsset) * 100 : 0;
        $debtToEquityRatio = $totEquityFinal > 0 ? ($totLiability / $totEquityFinal) * 100 : 0;

        // Working Capital Metrics
        $dso = $totRevenue > 0 ? ($totPiutang / $totRevenue) * 365 : 45;
        $dsi = $totHpp > 0 ? ($totPersediaan / $totHpp) * 365 : 60;
        $dpo = $totHpp > 0 ? ($totHutangUsaha / $totHpp) * 365 : 30;
        $ccc = $dso + $dsi - $dpo; // Cash Conversion Cycle

        // Format angka helper
        $fmt = function($num) {
            return ($num < 0 ? '(' . number_format(abs($num), 2) . ')' : number_format($num, 2));
        };

        echo "<!DOCTYPE html>
