<script>
    function switchPillar(pillarId) {
        var tabs = document.querySelectorAll('.pillar-tab');
        var contents = document.querySelectorAll('.pillar-content');

        for (var i = 0; i < contents.length; i++) {
            contents[i].classList.remove('active');
        }
        for (var j = 0; j < tabs.length; j++) {
            tabs[j].classList.remove('active');
            if (tabs[j].getAttribute('onclick') && tabs[j].getAttribute('onclick').indexOf(pillarId) !== -1) {
                tabs[j].classList.add('active');
            }
        }

        var targetPillar = document.getElementById(pillarId);
        if (targetPillar) {
            targetPillar.classList.add('active');
        }
    }

    function switchSubTab(pillarId, subId) {
        var subTabs = document.querySelectorAll('#' + pillarId + ' .sub-tab');
        var subContents = document.querySelectorAll('#' + pillarId + ' .sub-content');

        for (var i = 0; i < subContents.length; i++) {
            subContents[i].style.display = 'none';
        }
        for (var j = 0; j < subTabs.length; j++) {
            subTabs[j].classList.remove('active');
            if (subTabs[j].getAttribute('onclick') && subTabs[j].getAttribute('onclick').indexOf(subId) !== -1) {
                subTabs[j].classList.add('active');
            }
        }

        var targetContent = document.getElementById(subId);
        if (targetContent) {
            targetContent.style.display = 'block';
        }
    }

    function exportCurrentReportCSV() {
        var activePillar = document.querySelector('.pillar-content.active');
        if (!activePillar) return;

        var tables = activePillar.querySelectorAll('table');
        var table = null;
        for (var t = 0; t < tables.length; t++) {
            if (tables[t].offsetParent !== null) {
                table = tables[t];
                break;
            }
        }
        if (!table && tables.length > 0) {
            table = tables[0];
        }

        if (!table) {
            alert('Tidak ada tabel data pada tampilan saat ini.');
            return;
        }

        var csv = [];
        var rows = table.querySelectorAll('tr');
        for (var i = 0; i < rows.length; i++) {
            var row = [];
            var cols = rows[i].querySelectorAll('td, th');
            for (var j = 0; j < cols.length; j++) {
                var text = (cols[j].innerText || '').replace(/\\s+/g, ' ').replace(/\"/g, '\"\"').trim();
                row.push('\"' + text + '\"');
            }
            if (row.length > 0) csv.push(row.join(';'));
        }

        var csvContent = '\\uFEFF' + csv.join('\\n');
        var blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
        var url = URL.createObjectURL(blob);
        var a = document.createElement('a');
        a.href = url;
        a.download = 'corporate_finance_report_' + activePillar.id + '_' + new Date().toISOString().slice(0,10) + '.csv';
        document.body.appendChild(a);
        a.click();
        document.body.removeChild(a);
    }
</script>

</body>
</html>";
