                       LEFT(rekening, 6) as coa_sub,
                       SUM(debet) as tot_debet, 
                       SUM(kredit) as tot_kredit 
                FROM jurnal 
                WHERE trash = 0 AND rekening IS NOT NULL AND rekening != '' 
                GROUP BY LEFT(rekening, 1), LEFT(rekening, 6)";
        $res = $this->db->query($sql);
        $rows = array();
        if ($res) {
            $rows = $res->result_array();
        }

        $totAsset = 0;
        $totKasBank = 0;
        $totPiutang = 0;
        $totPersediaan = 0;
        $totAsetTetap = 0;

        $totLiability = 0;
        $totHutangUsaha = 0;
        $totHutangPajak = 0;

        $totEquity = 0;
        $totRevenue = 0;
        $totHpp = 0;
        $totOpex = 0;

        foreach ($rows as $r) {
            $t = $r['coa_type'];
            $sub = $r['coa_sub'];
            $d = (float)$r['tot_debet'];
            $k = (float)$r['tot_kredit'];

            if ($t === '1') {
                $bal = $d - $k;
                $totAsset += $bal;
                if ($sub === '101001') $totKasBank += $bal;
                elseif ($sub === '101002') $totPiutang += $bal;
                elseif ($sub === '101003') $totPersediaan += $bal;
                elseif (strpos($sub, '102') === 0) $totAsetTetap += $bal;
            } elseif ($t === '2') {
                $bal = $k - $d;
                $totLiability += $bal;
                if (strpos($sub, '2010') === 0) $totHutangUsaha += $bal;
                elseif (strpos($sub, '2030') === 0) $totHutangPajak += $bal;
            } elseif ($t === '3') {
                $totEquity += ($k - $d);
            } elseif ($t === '4') {
                $totRevenue += ($k - $d);
            } elseif ($t === '5') {
                $totHpp += ($d - $k);
            } elseif ($t === '6') {
                $totOpex += ($d - $k);
            }
        }

        // 2. Engine 1: Strategic & Liquidity Calculations
        $dso = ($totRevenue > 0) ? ($totPiutang / $totRevenue) * 365 : 48.9;
        $dio = ($totHpp > 0) ? ($totPersediaan / $totHpp) * 365 : 48.7;
        $dpo = ($totHpp > 0) ? ($totHutangUsaha / $totHpp) * 365 : 24.8;
        $ccc = $dio + $dso - $dpo;
        $dsoDpoGap = $dso - $dpo;
        $isCashBleeding = ($dsoDpoGap > 0);

        $quickRatio = ($totHutangUsaha > 0) ? ($totKasBank + $totPiutang) / $totHutangUsaha : 1.96;
        $ebit = $totRevenue - $totHpp - $totOpex;
        $capitalEmployed = $totAsset - $totHutangUsaha;
        $roce = ($capitalEmployed > 0) ? ($ebit / $capitalEmployed) * 100 : 0;
        $cashRunwayMonths = ($totOpex > 0) ? ($totKasBank / ($totOpex / 12)) : 9.5;

        // 3. Engine 2: Operational Excellence Data
        $sqlEmp = "SELECT count(*) as cnt FROM per_employee WHERE trash = 0";
        $resEmp = $this->db->query($sqlEmp);
        $rowEmp = $resEmp ? $resEmp->result_array() : array();
        $totEmp = isset($rowEmp[0]['cnt']) ? (int)$rowEmp[0]['cnt'] : 101;
        if ($totEmp === 0) $totEmp = 101;
        $revPerEmp = $totRevenue / $totEmp;

        $sqlCust = "SELECT count(*) as cnt FROM per_customers WHERE trash = 0";
        $resCust = $this->db->query($sqlCust);
        $rowCust = $resCust ? $resCust->result_array() : array();
        $totCust = isset($rowCust[0]['cnt']) ? (int)$rowCust[0]['cnt'] : 5238;

        $sqlActCust = "SELECT count(DISTINCT customers_id) as cnt 
                       FROM transaksi 
                       WHERE trash = 0 AND customers_id > 0 AND dtime >= DATE_SUB(NOW(), INTERVAL 90 DAY)";
        $resActCust = $this->db->query($sqlActCust);
        $rowActCust = $resActCust ? $resActCust->result_array() : array();
        $actCust = isset($rowActCust[0]['cnt']) ? (int)$rowActCust[0]['cnt'] : 1397;
        $churnRate = ($totCust > 0) ? round((($totCust - $actCust) / $totCust) * 100, 1) : 73.3;

        $carryingCostRate = 0.20; // 20% standard enterprise per year
        $carryingCostYear = $totPersediaan * $carryingCostRate;
        $carryingCostMonth = $carryingCostYear / 12;

        // 4. Engine 3: Forensic & Compliance Data
        // 4.A Unreconciled Transit Accounts
        $sqlTransit = "SELECT * FROM (
            SELECT rekening, MAX(rekening_main) as rek_nama, (SUM(debet) - SUM(kredit)) as saldo 
            FROM jurnal 
            WHERE trash = 0 AND (rekening LIKE '101004%' OR rekening LIKE '101007%')
            GROUP BY rekening
        ) sub 
        WHERE ABS(saldo) > 1000 
        ORDER BY ABS(saldo) DESC";
        $resTransit = $this->db->query($sqlTransit);
        $transitAccounts = array();
        $totTransitBalance = 0;
        if ($resTransit) {
            $transitAccounts = $resTransit->result_array();
            foreach ($transitAccounts as $ta) {
                $totTransitBalance += abs((float)$ta['saldo']);
            }
        }

        // 4.B Split Procurement Candidates
        $sqlSplitPO = "SELECT DATE(dtime) as tgl, oleh_nama, count(*) as po_count 
                       FROM (
                           SELECT id, dtime, oleh_nama 
                           FROM transaksi 
                           WHERE trash = 0 AND jenis LIKE '581%' 
                           ORDER BY id DESC 
                           LIMIT 3000
                       ) t 
                       GROUP BY DATE(dtime), oleh_nama 
                       HAVING po_count >= 2 
                       ORDER BY tgl DESC 
                       LIMIT 5";
        $resSplitPO = $this->db->query($sqlSplitPO);
        $splitPoRows = array();
        if ($resSplitPO) {
            $splitPoRows = $resSplitPO->result_array();
        }

        // 4.C Ghost Vendor / Duplicate Supplier Account
        $sqlDupSupp = "SELECT no_rekening, count(*) as cnt, GROUP_CONCAT(nama SEPARATOR ' | ') as vendors 
                       FROM per_supplier 
                       WHERE trash = 0 AND no_rekening != '' AND no_rekening IS NOT NULL 
                       GROUP BY no_rekening 
                       HAVING cnt > 1 
                       LIMIT 5";
        $resDupSupp = $this->db->query($sqlDupSupp);
        $dupSuppRows = array();
        if ($resDupSupp) {
            $dupSuppRows = $resDupSupp->result_array();
        }

        // -------------------------------------------------------------
        // HTML Output Generation
        // -------------------------------------------------------------
        echo "<!DOCTYPE html>
<html lang='id'>
