            <div class='kpi-val' style='color:" . ($isCashBleeding ? "#ef4444" : "#10b981") . ";'>" . ($dsoDpoGap > 0 ? "+" : "") . round($dsoDpoGap, 1) . " Hari</div>
            <div class='kpi-sub' style='color:" . ($isCashBleeding ? "#ef4444" : "#10b981") . "; font-weight:700;'>" . ($isCashBleeding ? "⚠️ CASH BLEEDING WARNING" : "✅ HEALTHY CASH FLOW") . "</div>
        </div>
        <div class='kpi-card'>
            <div class='kpi-label'>Quick Ratio (Acid-Test)</div>
            <div class='kpi-val' style='color:#10b981;'>" . number_format($quickRatio, 2) . "x</div>
            <div class='kpi-sub'>Solven &bull; Kas + Piutang vs Hutang</div>
        </div>
        <div class='kpi-card'>
            <div class='kpi-label'>Revenue Per Employee</div>
            <div class='kpi-val' style='color:#0f172a;'>Rp " . number_format($revPerEmp / 1000000000, 2) . " M</div>
            <div class='kpi-sub'>" . $totEmp . " Karyawan Aktif Terdaftar</div>
        </div>
        <div class='kpi-card'>
            <div class='kpi-label'>Customer Churn Rate</div>
            <div class='kpi-val' style='color:#d97706;'>" . $churnRate . "%</div>
            <div class='kpi-sub'>" . number_format($actCust) . " Aktif / " . number_format($totCust) . " Pelanggan</div>
        </div>
        <div class='kpi-card alert-bleeding'>
            <div class='kpi-label'>Unreconciled Transit</div>
            <div class='kpi-val' style='color:#ef4444;'>Rp " . number_format($totTransitBalance / 1000000000, 2) . " M</div>
            <div class='kpi-sub'>" . count($transitAccounts) . " Akun Perantara &gt; 48 Jam</div>
        </div>
    </div>

    <!-- Navigation Tabs: The Triple-Engine Framework -->
    <div class='engine-nav'>
        <div class='engine-tab active' onclick='switchEngineTab(\"engine-strategic\")'>
            <span>💎 1. STRATEGIC &amp; LIQUIDITY ENGINE</span>
            <span class='badge badge-blue'>CFO &amp; CEO Command</span>
        </div>
        <div class='engine-tab' onclick='switchEngineTab(\"engine-operations\")'>
