        <div class='tab-btn' onclick=\"switchCoretaxTab('tab-compliance')\">🛡️ Kepatuhan Data Master</div>
        <div class='tab-btn' onclick=\"switchCoretaxTab('tab-pathway')\">🔑 Jalur Integrasi API</div>
        <div class='tab-btn' onclick=\"switchCoretaxTab('tab-generator')\">⚙️ XML Generator</div>
    </div>

    <!-- ============================================== -->
    <!-- TAB 1: RINGKASAN PAJAK -->
    <!-- ============================================== -->
    <div id='tab-overview' class='tab-panel active'>";

        // Profil Pajak Perusahaan
        $companyNama = htmlspecialchars(isset($company['nama']) ? $company['nama'] : 'N/A');
        $companyNpwp = htmlspecialchars(isset($company['npwp']) ? $company['npwp'] : '-');
        $companyAlamat = htmlspecialchars(isset($company['alamat']) ? $company['alamat'] : '-');
        $companyUsaha = htmlspecialchars(isset($company['jenis_usaha']) ? $company['jenis_usaha'] : '-');
        $pkpBadge = $isPKP ? "<span class='badge badge-green'>PKP Terdaftar</span>" : "<span class='badge badge-amber'>Non-PKP / Belum Dikonfirmasi</span>";

        echo "
