                        <th class='text-right'>Total PPN Tercatat</th>
                        <th class='text-center'>Kontribusi %</th>
                    </tr>
                </thead>
                <tbody>";

        $totalAllPpn = 0;
        foreach ($ppnByJenis as $pj) {
            $totalAllPpn += (float)$pj['total_ppn'];
        }

        $noUrut = 1;
        foreach ($ppnByJenis as $pj) {
            $pctContrib = ($totalAllPpn > 0) ? round(((float)$pj['total_ppn'] / $totalAllPpn) * 100, 1) : 0;
            $jenisLabel = htmlspecialchars($pj['jenis']);
            echo "<tr>
                    <td>" . $noUrut . "</td>
                    <td><code>" . $jenisLabel . "</code></td>
                    <td class='text-center'>" . number_format((int)$pj['cnt'], 0, ',', '.') . "</td>
                    <td class='text-right' style='font-weight:700;'>Rp " . number_format((float)$pj['total_ppn'], 0, ',', '.') . "</td>
                    <td class='text-center'><span class='badge badge-blue'>" . $pctContrib . "%</span></td>
                </tr>";
            $noUrut++;
        }

        echo "</tbody>
