    <script>
        window.switchFieldServiceTab = function(tabId) {
            var tabs = document.querySelectorAll('.tab-btn');
            var panels = document.querySelectorAll('.tab-panel');

            for (var i = 0; i < panels.length; i++) {
                panels[i].classList.remove('active');
            }
            for (var j = 0; j < tabs.length; j++) {
                tabs[j].classList.remove('active');
                var oc = tabs[j].getAttribute('onclick') || '';
                if (oc.indexOf(tabId) !== -1) {
                    tabs[j].classList.add('active');
                }
            }

            var target = document.getElementById(tabId);
            if (target) target.classList.add('active');
        };

        window.exportFieldServiceCSV = function(tableId, filename) {
            var table = document.getElementById(tableId);
            if (!table) {
                alert('Tabel tidak ditemukan.');
                return;
            }

            var csv = [];
            var rows = table.querySelectorAll('tr');
            for (var i = 0; i < rows.length; i++) {
                var row = [];
                var cols = rows[i].querySelectorAll('td, th');
                for (var j = 0; j < cols.length; j++) {
                    var text = (cols[j].innerText || '').replace(/\\s+/g, ' ').replace(/\"/g, '\"\"').trim();
                    row.push('\"' + text + '\"');
                }
                if (row.length > 0) csv.push(row.join(';'));
            }

            var csvContent = '\\uFEFF' + csv.join('\\n');
            var blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
            var url = URL.createObjectURL(blob);
            var a = document.createElement('a');
            a.href = url;
            a.download = filename + '_' + new Date().toISOString().slice(0,10) + '.csv';
            document.body.appendChild(a);
            a.click();
            document.body.removeChild(a);
        };
    </script>
