                                    <div class="diagnosa-box <?php echo $box_class; ?>">
                                        <b><?php echo htmlspecialchars($row['diagnosa_txt']); ?></b><br>
                                        <span class="text-muted">Solusi: <?php echo htmlspecialchars($row['solusi_txt']); ?></span>
