// Function logEditProjectProduk to be added to Tool.php

    // START OF COMPLETE REPEATED LOGIC
    /**
     * Tool Khusus Audit & Manajemen Log Edit Project (project_produk_edit_log)
     * URL: base_url() . "Tool/logEditProjectProduk"
     */
    public function logEditProjectProduk()
    {
        $this->load->helper("url");
        $this->load->helper("he_url");
        $this->load->helper("he_misc");

        $logId = isset($_GET['log_id']) ? (int)$_GET['log_id'] : (isset($_POST['log_id']) ? (int)$_POST['log_id'] : 0);
        $filterProjectId = isset($_GET['project_id']) ? (int)$_GET['project_id'] : 0;
        $filterKeyword = isset($_GET['keyword']) ? trim($_GET['keyword']) : '';
        $filterState = (isset($_GET['state']) && $_GET['state'] !== '') ? (int)$_GET['state'] : '';

        $msgSuccess = "";
        $msgError = "";
        $executedQueries = array();

        // 1. Handle POST Actions
        if ($this->input->server('REQUEST_METHOD') === 'POST' && isset($_POST['action'])) {
            $action = trim($_POST['action']);

            // Aksi 1: Restore Snapshot ke Live Registry
            if ($action === 'restore_snapshot') {
                $targetLogId = isset($_POST['log_id']) ? (int)$_POST['log_id'] : 0;
                $targetSource = isset($_POST['target_source']) ? trim($_POST['target_source']) : 'old'; // 'old' atau 'new'
                $syncPaymentSource = isset($_POST['sync_payment_source']) && $_POST['sync_payment_source'] == '1';

                $this->db->where('id', $targetLogId);
                $targetLog = $this->db->get('project_produk_edit_log')->row();

                if (!$targetLog) {
                    $msgError = "Log ID #$targetLogId tidak ditemukan.";
                } else {
                    $jsonRaw = ($targetSource === 'new') ? $targetLog->data_new : $targetLog->data_old;
                    $decodedJson = !empty($jsonRaw) ? json_decode($jsonRaw, true) : array();

                    if (empty($decodedJson) || !is_array($decodedJson)) {
                        $msgError = "Snapshot data " . strtoupper($targetSource) . " kosong atau tidak memiliki riwayat data yang valid.";
                    } else {
                        // Ambil timestamp snapshot terbaru
                        $timestampKey = key($decodedJson);
                        $trxDataMap = isset($decodedJson[$timestampKey]) ? $decodedJson[$timestampKey] : array();

                        if (empty($trxDataMap) || !is_array($trxDataMap)) {
                            $msgError = "Tidak ditemukan data transaksi pada snapshot " . strtoupper($targetSource) . ".";
                        } else {
                            $this->db->trans_start();

                            // Ambil master project
                            $this->db->where('id', $targetLog->project_id);
                            $projectRow = $this->db->get('project_produk')->row();

                            $updatedTrx = array();
                            foreach ($trxDataMap as $tId => $parts) {
                                $tId = (int)$tId;
                                if ($tId <= 0 || !is_array($parts)) {
                                    continue;
                                }

                                $blobMain = isset($parts['main']) ? $parts['main'] : '';
                                $blobItems3 = isset($parts['items3']) ? $parts['items3'] : '';
                                $blobItems4 = isset($parts['items4']) ? $parts['items4'] : '';
                                $blobItems5 = isset($parts['items5']) ? $parts['items5'] : '';
                                $blobItems7 = isset($parts['items7']) ? $parts['items7'] : '';

                                $this->db->select('transaksi_id');
                                $this->db->where('transaksi_id', $tId);
                                $regExist = $this->db->get('transaksi_data_registry')->row();

                                $dataReg = array(
                                    'main' => $blobMain,
                                    'items3' => $blobItems3,
                                    'items4' => $blobItems4,
                                    'items5' => $blobItems5,
                                    'items7' => $blobItems7,
                                );

                                if ($regExist) {
                                    $this->db->where('transaksi_id', $tId);
                                    $this->db->update('transaksi_data_registry', $dataReg);
                                } else {
                                    $dataReg['transaksi_id'] = $tId;
                                    $this->db->insert('transaksi_data_registry', $dataReg);
                                }
                                $executedQueries[] = $this->db->last_query();
                                $updatedTrx[] = $tId;
                            }

                            // Sync Payment Source jika dicentang
                            if ($syncPaymentSource && $projectRow) {
                                $projHargaDpp = isset($projectRow->harga) ? (float)$projectRow->harga : 0;
                                $firstTrxParts = reset($trxDataMap);

                                $arrItems3 = isset($firstTrxParts['items3']) ? blobDecode($firstTrxParts['items3']) : array();
                                $arrItems4 = isset($firstTrxParts['items4']) ? blobDecode($firstTrxParts['items4']) : array();
                                $arrItems5 = isset($firstTrxParts['items5']) ? blobDecode($firstTrxParts['items5']) : array();

                                if (!is_array($arrItems3)) { $arrItems3 = array(); }
                                if (!is_array($arrItems4)) { $arrItems4 = array(); }
                                if (!is_array($arrItems5)) { $arrItems5 = array(); }

                                // 1. Plafon 7499
                                if ($projHargaDpp > 0) {
                                    $this->db->where('project_id', $targetLog->project_id);
                                    $this->db->where('target_jenis', '7499');
                                    $tps7499 = $this->db->get('transaksi_payment_source')->row();
                                    if ($tps7499) {
                                        $this->db->where('id', $tps7499->id);
                                        $this->db->update('transaksi_payment_source', array(
                                            'tagihan' => $projHargaDpp,
                                            'sisa' => $projHargaDpp - (float)$tps7499->terbayar,
                                            'extern_nilai2' => $projHargaDpp,
                                            'dtime' => date('Y-m-d H:i:s'),
                                            'fulldate' => date('Y-m-d'),
                                        ));
                                        $executedQueries[] = $this->db->last_query();
                                    }
                                }

                                // 2. Retensi 7488
                                $sumRetensiHarga = 0;
                                foreach ($arrItems5 as $retItem) {
                                    if (isset($retItem['harga'])) {
                                        $sumRetensiHarga += (float)$retItem['harga'];
                                    }
                                }
                                if ($sumRetensiHarga > 0) {
                                    $retensiExcl = round($sumRetensiHarga / 1.11);
                                    $this->db->where('project_id', $targetLog->project_id);
                                    $this->db->where('target_jenis', '7488');
                                    $this->db->where('label', 'retensi');
                                    $tpsRetensi = $this->db->get('transaksi_payment_source')->row();
                                    if ($tpsRetensi) {
                                        $this->db->where('id', $tpsRetensi->id);
                                        $this->db->update('transaksi_payment_source', array(
                                            'tagihan' => $retensiExcl,
                                            'sisa' => $retensiExcl - (float)$tpsRetensi->terbayar,
                                            'ppn' => round(($retensiExcl * 11) / 100),
                                            'extern_nilai2' => $projHargaDpp,
                                            'dtime' => date('Y-m-d H:i:s'),
                                            'fulldate' => date('Y-m-d'),
                                        ));
                                        $executedQueries[] = $this->db->last_query();
                                    }
                                }

                                // 3. Termin 7488
                                $sumTerminHarga = 0;
                                foreach ($arrItems3 as $terItem) {
                                    if (isset($terItem['harga'])) {
                                        $sumTerminHarga += (float)$terItem['harga'];
                                    }
                                }
                                if ($sumTerminHarga > 0) {
                                    $terminExcl = round($sumTerminHarga / 1.11);
                                    $this->db->where('project_id', $targetLog->project_id);
                                    $this->db->where('target_jenis', '7488');
                                    $this->db->where('label', 'termin');
                                    $tpsTermin = $this->db->get('transaksi_payment_source')->row();
                                    if ($tpsTermin) {
                                        $this->db->where('id', $tpsTermin->id);
                                        $this->db->update('transaksi_payment_source', array(
                                            'tagihan' => $terminExcl,
                                            'sisa' => $terminExcl - (float)$tpsTermin->terbayar,
                                            'ppn' => round(($terminExcl * 11) / 100),
                                            'extern_nilai2' => $projHargaDpp,
                                            'dtime' => date('Y-m-d H:i:s'),
                                            'fulldate' => date('Y-m-d'),
                                        ));
                                        $executedQueries[] = $this->db->last_query();
                                    }
                                }
                            }

                            $this->db->trans_complete();

                            if ($this->db->trans_status() === FALSE) {
                                $msgError = "Terjadi kegagalan transaksi database saat merestore snapshot.";
                            } else {
                                $msgSuccess = "Berhasil me-restore snapshot " . strtoupper($targetSource) . " ke tabel transaksi_data_registry untuk transaksi: #" . implode(', #', $updatedTrx) . " (Project #{$targetLog->project_id}).";
                            }
                        }
                    }
                }
            }

            // Aksi 2: Ubah State Log
            elseif ($action === 'change_state') {
                $targetLogId = isset($_POST['log_id']) ? (int)$_POST['log_id'] : 0;
                $newState = isset($_POST['new_state']) ? (int)$_POST['new_state'] : 2;

                if ($targetLogId > 0 && in_array($newState, array(1, 2))) {
                    $this->db->where('id', $targetLogId);
                    $this->db->update('project_produk_edit_log', array('state' => $newState));
                    $executedQueries[] = $this->db->last_query();
                    $stateLabel = ($newState === 1) ? '1 (Edit in Progress / Open)' : '2 (Saved / Pending Auth)';
                    $msgSuccess = "State untuk Log ID #$targetLogId berhasil diperbarui menjadi: $stateLabel.";
                } else {
                    $msgError = "Parameter update state tidak valid.";
                }
            }
        }

        // 2. Query Daftar Log (Tabel Utama) - Optimasi: Hanya pilih kolom yang dibutuhkan, hindari load blob data_old/data_new
        $this->db->select("id, project_id, project_nama, state, edit_count, date_edited, edit_by_name, date_saved, saved_by_name, approve_by_nama, date_approved, 
            (CASE WHEN data_old IS NOT NULL AND data_old != '[]' AND data_old != '' THEN 1 ELSE 0 END) AS has_old,
            (CASE WHEN data_new IS NOT NULL AND data_new != '[]' AND data_new != '' THEN 1 ELSE 0 END) AS has_new");
        $this->db->from('project_produk_edit_log');
        if ($filterProjectId > 0) {
            $this->db->where('project_id', $filterProjectId);
        }
        if ($filterKeyword !== '') {
            $this->db->group_start();
            $this->db->like('project_nama', $filterKeyword);
            $this->db->or_like('edit_by_name', $filterKeyword);
            $this->db->or_like('saved_by_name', $filterKeyword);
            $this->db->group_end();
        }
        if ($filterState !== '') {
            $this->db->where('state', (int)$filterState);
        }
        $this->db->order_by('id', 'DESC');
        $this->db->limit(100);
        $logList = $this->db->get()->result();

        // 3. Detail Inspeksi Log Terpilih
        $selectedLog = null;
        $decodedOld = array();
        $decodedNew = array();
        $allTrxIds = array();
        $trxComparisons = array();
        $projectData = null;
        $liveTpsList = array();

        if ($logId > 0) {
            $this->db->where('id', $logId);
            $selectedLog = $this->db->get('project_produk_edit_log')->row();

            if ($selectedLog) {
                // Ambil master project
                $this->db->where('id', $selectedLog->project_id);
                $projectData = $this->db->get('project_produk')->row();

                // Parsing JSON data_old dan data_new
                $rawOld = !empty($selectedLog->data_old) ? json_decode($selectedLog->data_old, true) : array();
                $rawNew = !empty($selectedLog->data_new) ? json_decode($selectedLog->data_new, true) : array();

                $oldTimestamp = is_array($rawOld) ? key($rawOld) : '';
                $newTimestamp = is_array($rawNew) ? key($rawNew) : '';

                $oldTrxMap = ($oldTimestamp && isset($rawOld[$oldTimestamp]) && is_array($rawOld[$oldTimestamp])) ? $rawOld[$oldTimestamp] : array();
                $newTrxMap = ($newTimestamp && isset($rawNew[$newTimestamp]) && is_array($rawNew[$newTimestamp])) ? $rawNew[$newTimestamp] : array();

                // Himpun seluruh transaksi ID yang ada di log maupun master project (WAJIB cast integer murni agar index PRIMARY range scan berjalan optimal tanpa implicit string conversion!)
                $allTrxIds = array();
                if (!empty($oldTrxMap)) {
                    foreach (array_keys($oldTrxMap) as $tK) {
                        $intVal = (int)$tK;
                        if ($intVal > 0) { $allTrxIds[] = $intVal; }
                    }
                }
                if (!empty($newTrxMap)) {
                    foreach (array_keys($newTrxMap) as $tK) {
                        $intVal = (int)$tK;
                        if ($intVal > 0) { $allTrxIds[] = $intVal; }
                    }
                }
                if ($projectData) {
                    if (!empty($projectData->quot_id) && (int)$projectData->quot_id > 0) { $allTrxIds[] = (int)$projectData->quot_id; }
                    if (!empty($projectData->project_start_id) && (int)$projectData->project_start_id > 0) { $allTrxIds[] = (int)$projectData->project_start_id; }
                    if (!empty($projectData->transaksi_id) && (int)$projectData->transaksi_id > 0) { $allTrxIds[] = (int)$projectData->transaksi_id; }
                }
                $allTrxIds = array_values(array_unique(array_filter($allTrxIds)));

                // Ambil data LIVE dari transaksi_data_registry (Optimasi: hanya 6 kolom yang dibutuhkan, bukan 62 longblob!)
                $liveRegMap = array();
                if (!empty($allTrxIds)) {
                    $this->db->select('transaksi_id, main, items3, items4, items5, items7');
                    $this->db->where_in('transaksi_id', $allTrxIds);
                    $liveRegRows = $this->db->get('transaksi_data_registry')->result();
                    if (!empty($liveRegRows)) {
                        foreach ($liveRegRows as $lrr) {
                            $liveRegMap[$lrr->transaksi_id] = $lrr;
                        }
                    }
                }

                // Ambil data LIVE dari transaksi_payment_source (Optimasi: kolom spesifik & terindeks)
                $this->db->select('id, jenis, target_jenis, label, nomer, tagihan, terbayar, sisa, ppn, payment_source_keterangan');
                $this->db->where('project_id', $selectedLog->project_id);
                $this->db->order_by('id', 'ASC');
                $liveTpsList = $this->db->get('transaksi_payment_source')->result();

                // Bangun struktur perbandingan per transaksi ID
                foreach ($allTrxIds as $tId) {
                    $oldPart = isset($oldTrxMap[$tId]) ? $oldTrxMap[$tId] : array();
                    $newPart = isset($newTrxMap[$tId]) ? $newTrxMap[$tId] : array();
                    $livePart = isset($liveRegMap[$tId]) ? $liveRegMap[$tId] : null;

                    // Decode dengan blobDecode()
                    $decOldMain = isset($oldPart['main']) ? blobDecode($oldPart['main']) : array();
                    $decOldItems3 = isset($oldPart['items3']) ? blobDecode($oldPart['items3']) : array();
                    $decOldItems4 = isset($oldPart['items4']) ? blobDecode($oldPart['items4']) : array();
                    $decOldItems5 = isset($oldPart['items5']) ? blobDecode($oldPart['items5']) : array();
                    $decOldItems7 = isset($oldPart['items7']) ? blobDecode($oldPart['items7']) : array();

                    $decNewMain = isset($newPart['main']) ? blobDecode($newPart['main']) : array();
                    $decNewItems3 = isset($newPart['items3']) ? blobDecode($newPart['items3']) : array();
                    $decNewItems4 = isset($newPart['items4']) ? blobDecode($newPart['items4']) : array();
                    $decNewItems5 = isset($newPart['items5']) ? blobDecode($newPart['items5']) : array();
                    $decNewItems7 = isset($newPart['items7']) ? blobDecode($newPart['items7']) : array();

                    $decLiveMain = ($livePart && !empty($livePart->main)) ? blobDecode($livePart->main) : array();
                    $decLiveItems3 = ($livePart && !empty($livePart->items3)) ? blobDecode($livePart->items3) : array();
                    $decLiveItems4 = ($livePart && !empty($livePart->items4)) ? blobDecode($livePart->items4) : array();
                    $decLiveItems5 = ($livePart && !empty($livePart->items5)) ? blobDecode($livePart->items5) : array();
                    $decLiveItems7 = ($livePart && !empty($livePart->items7)) ? blobDecode($livePart->items7) : array();

                    if (!is_array($decOldMain)) { $decOldMain = array(); }
                    if (!is_array($decOldItems3)) { $decOldItems3 = array(); }
                    if (!is_array($decOldItems4)) { $decOldItems4 = array(); }
                    if (!is_array($decOldItems5)) { $decOldItems5 = array(); }
                    if (!is_array($decOldItems7)) { $decOldItems7 = array(); }

                    if (!is_array($decNewMain)) { $decNewMain = array(); }
                    if (!is_array($decNewItems3)) { $decNewItems3 = array(); }
                    if (!is_array($decNewItems4)) { $decNewItems4 = array(); }
                    if (!is_array($decNewItems5)) { $decNewItems5 = array(); }
                    if (!is_array($decNewItems7)) { $decNewItems7 = array(); }

                    if (!is_array($decLiveMain)) { $decLiveMain = array(); }
                    if (!is_array($decLiveItems3)) { $decLiveItems3 = array(); }
                    if (!is_array($decLiveItems4)) { $decLiveItems4 = array(); }
                    if (!is_array($decLiveItems5)) { $decLiveItems5 = array(); }
                    if (!is_array($decLiveItems7)) { $decLiveItems7 = array(); }

                    // Deteksi perubahan
                    $isMainChanged = (serialize($decOldMain) !== serialize($decNewMain));
                    $isItems3Changed = (serialize($decOldItems3) !== serialize($decNewItems3));
                    $isItems4Changed = (serialize($decOldItems4) !== serialize($decNewItems4));
                    $isItems5Changed = (serialize($decOldItems5) !== serialize($decNewItems5));
                    $isItems7Changed = (serialize($decOldItems7) !== serialize($decNewItems7));

                    $trxComparisons[$tId] = array(
                        'transaksi_id' => $tId,
                        'old' => array(
                            'main' => $decOldMain,
                            'items3' => $decOldItems3,
                            'items4' => $decOldItems4,
                            'items5' => $decOldItems5,
                            'items7' => $decOldItems7,
                        ),
                        'new' => array(
                            'main' => $decNewMain,
                            'items3' => $decNewItems3,
                            'items4' => $decNewItems4,
                            'items5' => $decNewItems5,
                            'items7' => $decNewItems7,
                        ),
                        'live' => array(
                            'main' => $decLiveMain,
                            'items3' => $decLiveItems3,
                            'items4' => $decLiveItems4,
                            'items5' => $decLiveItems5,
                            'items7' => $decLiveItems7,
                        ),
                        'changed' => array(
                            'main' => $isMainChanged,
                            'items3' => $isItems3Changed,
                            'items4' => $isItems4Changed,
                            'items5' => $isItems5Changed,
                            'items7' => $isItems7Changed,
                        ),
                    );
                }
            }
        }

