    /**
     * Tool Audit & Rekonsiliasi Payment Source Project berbasis SOT Jurnal Piutang
     * Memverifikasi apakah nilai2 di payment_source sinkron dengan nilai kontrak awal,
     * dibuktikan dari Jurnal Masuk Piutang Konsumen (Rekening 1010020010),
     * serta memantau 4 kolom (tagihan, terbayar, returned, sisa) pada penerbitan faktur kasir 749
     * berdasarkan 3 _key (termin, retensi, dp) dan memastikan kepastian basis DPP vs Gross (DPP+PPN).
     */
    public function auditPaymentSourceProject()
    {
        $this->load->helper("url");
        $this->load->helper("he_url");
        $this->load->helper("he_misc");

        $filterProjectId = isset($_GET['project_id']) ? (int)$_GET['project_id'] : (isset($_POST['project_id']) ? (int)$_POST['project_id'] : 0);
        $filterSearch    = isset($_GET['search']) ? trim((string)$_GET['search']) : '';
        $filterStatus    = isset($_GET['filter']) ? trim((string)$_GET['filter']) : 'all'; // all, anomaly, basis_dpp, sisa_mismatch, missing_key, matched
        $isJson          = (isset($_GET['json']) && $_GET['json'] == 1);

        $msgSuccess = "";
        $msgError   = "";

        // =========================================================================
        // 1. POST ACTION HANDLER: PERBAIKAN ONE-CLICK SECARA AMAN (DB TRANSACTION)
        // =========================================================================
        if ($this->input->server('REQUEST_METHOD') === 'POST' && isset($_POST['action_repair'])) {
            $action = trim((string)$_POST['action_repair']);
            $targetId = isset($_POST['target_id']) ? (int)$_POST['target_id'] : 0;
            $pId = isset($_POST['project_id']) ? (int)$_POST['project_id'] : 0;

            $this->db->trans_start();

            if ($action === 'fix_basis_to_gross' && $targetId > 0) {
                // Ubah faktur 749 yang salah tercatat DPP menjadi Gross (DPP + PPN 11%)
                $this->db->where('id', $targetId);
                $rowTps = $this->db->get('transaksi_payment_source')->row();
                if ($rowTps) {
                    $rawTag = (float)$rowTps->tagihan;
                    $rawTerb = (float)$rowTps->terbayar;
                    $rawRet = (float)$rowTps->returned;
                    $rawDisk = (float)$rowTps->diskon;
                    $ppnVal = isset($rowTps->ppn) && (float)$rowTps->ppn > 0 ? (float)$rowTps->ppn : round($rawTag * 0.11, 2);
                    $newTagihan = round($rawTag * 1.11, 2);
                    $newSisa = max(0, $newTagihan - $rawTerb - $rawRet - $rawDisk);

                    $this->db->where('id', $targetId);
                    $this->db->update('transaksi_payment_source', array(
                        'tagihan' => $newTagihan,
                        'sisa'    => $newSisa,
                        'ppn'     => $ppnVal,
                        'dpp_ppn' => $rawTag
                    ));
                    $msgSuccess = "Berhasil memperbaiki basis faktur #" . $targetId . " menjadi Gross (Incl. PPN Rp " . number_format($newTagihan) . ").";
                }
            } elseif ($action === 'fix_plafon_to_dpp' && $targetId > 0 && $pId > 0) {
                // Kembalikan plafon induk 7499 ke DPP murni dari project_produk.harga
                $this->db->where('id', $pId);
                $pRow = $this->db->get('project_produk')->row();
                if ($pRow) {
                    $kontrakDpp = (float)$pRow->harga;
                    $this->db->where('id', $targetId);
                    $rowTps = $this->db->get('transaksi_payment_source')->row();
                    if ($rowTps) {
                        $newSisa = max(0, $kontrakDpp - (float)$rowTps->terbayar);
                        $this->db->where('id', $targetId);
                        $this->db->update('transaksi_payment_source', array(
                            'tagihan' => $kontrakDpp,
                            'sisa'    => $newSisa
                        ));
                        $msgSuccess = "Berhasil mengembalikan Plafon Induk 7499 #" . $targetId . " ke DPP Kontrak (Rp " . number_format($kontrakDpp) . ").";
                    }
                }
            } elseif ($action === 'sync_terbayar_induk' && $pId > 0) {
                // Hitung total DPP faktur yang terbit dan update terbayar & sisa pada induk 7499
                $this->db->select('id, tagihan, ppn, dpp_ppn, target_jenis, _key');
                $this->db->where('project_id', $pId);
                $this->db->where_in('target_jenis', array('749', '7488'));
                $this->db->where('(cancel_dtime IS NULL OR cancel_dtime = "0000-00-00 00:00:00")', null, false);
                $fRows = $this->db->get('transaksi_payment_source')->result();

                $totDppIssued = 0;
                if (!empty($fRows)) {
                    foreach ($fRows as $fr) {
                        $fTag = (float)$fr->tagihan;
                        $fDpp = (float)$fr->dpp_ppn;
                        $fPpn = (float)$fr->ppn;
                        if ($fDpp > 0) {
                            $totDppIssued += $fDpp;
                        } elseif ($fPpn > 0 && abs($fTag - $fDpp) < 10) {
                            $totDppIssued += $fTag;
                        } else {
                            $totDppIssued += ($fTag / 1.11);
                        }
                    }
                }
                $totDppIssued = round($totDppIssued, 2);

                $this->db->where('project_id', $pId);
                $this->db->where('target_jenis', '7499');
                $indukList = $this->db->get('transaksi_payment_source')->result();
                if (!empty($indukList)) {
                    foreach ($indukList as $inRow) {
                        $newSisaInduk = max(0, (float)$inRow->tagihan - $totDppIssued);
                        $this->db->where('id', $inRow->id);
                        $this->db->update('transaksi_payment_source', array(
                            'terbayar' => $totDppIssued,
                            'sisa'     => $newSisaInduk
                        ));
                    }
                    $msgSuccess = "Berhasil menyinkronkan penyerapan terbayar Induk 7499 menjadi DPP Rp " . number_format($totDppIssued) . ".";
                }
            } elseif ($action === 'fix_sisa_formula' && $targetId > 0) {
                // Hitung ulang sisa = max(0, tagihan - terbayar - returned - diskon)
                $this->db->where('id', $targetId);
                $rowTps = $this->db->get('transaksi_payment_source')->row();
                if ($rowTps) {
                    $newSisa = max(0, (float)$rowTps->tagihan - (float)$rowTps->terbayar - (float)$rowTps->returned - (float)$rowTps->diskon);
                    $this->db->where('id', $targetId);
                    $this->db->update('transaksi_payment_source', array(
                        'sisa' => $newSisa
                    ));
                    $msgSuccess = "Berhasil mengoreksi sisa pada record #" . $targetId . " menjadi Rp " . number_format($newSisa) . ".";
                }
            } elseif ($action === 'fix_missing_key' && $targetId > 0) {
                $newKey = isset($_POST['new_key']) ? strtolower(trim((string)$_POST['new_key'])) : 'termin';
                if (!in_array($newKey, array('termin', 'dp', 'retensi'))) {
                    $newKey = 'termin';
                }
                $this->db->where('id', $targetId);
                $this->db->update('transaksi_payment_source', array(
                    '_key' => $newKey
                ));
                $msgSuccess = "Berhasil melengkapi _key pada record #" . $targetId . " menjadi '" . $newKey . "'.";
            } elseif ($action === 'auto_repair_project' && $pId > 0) {
                // Auto Repair Keseluruhan untuk Proyek Ini:
                // 1. Plafon Induk 7499 -> Set ke DPP project_produk.harga
                $this->db->where('id', $pId);
                $pRow = $this->db->get('project_produk')->row();
                if ($pRow) {
                    $kontrakDpp = (float)$pRow->harga;
                    $this->db->where('project_id', $pId);
                    $this->db->where('target_jenis', '7499');
                    $this->db->update('transaksi_payment_source', array(
                        'tagihan' => $kontrakDpp
                    ));

                    // 2. Faktur Kasir 749 -> Pastikan _key terisi dan sisa konsisten
                    $this->db->where('project_id', $pId);
                    $this->db->where('target_jenis', '749');
                    $t749List = $this->db->get('transaksi_payment_source')->result();
                    $totDppFaktur = 0;

                    if (!empty($t749List)) {
                        foreach ($t749List as $r749) {
                            $rKey = strtolower(trim((string)$r749->_key));
                            if (empty($rKey)) {
                                $rLabel = strtolower(trim((string)$r749->label));
                                $rKey = (strpos($rLabel, 'dp') !== false || strpos($rLabel, 'uang muka') !== false) ? 'dp' : ((strpos($rLabel, 'retensi') !== false) ? 'retensi' : 'termin');
                            }
                            $cTag = (float)$r749->tagihan;
                            $cTerb = (float)$r749->terbayar;
                            $cRet = (float)$r749->returned;
                            $cDisk = (float)$r749->diskon;
                            $cSisa = max(0, $cTag - $cTerb - $cRet - $cDisk);

                            $this->db->where('id', $r749->id);
                            $this->db->update('transaksi_payment_source', array(
                                '_key' => $rKey,
                                'sisa' => $cSisa
                            ));

                            $fDpp = (float)$r749->dpp_ppn > 0 ? (float)$r749->dpp_ppn : ($cTag / 1.11);
                            $totDppFaktur += $fDpp;
                        }
                    }

                    // 3. Update Plafon Induk 7499 terbayar & sisa
                    $totDppFaktur = round($totDppFaktur, 2);
                    $newPlafonSisa = max(0, $kontrakDpp - $totDppFaktur);
                    $this->db->where('project_id', $pId);
                    $this->db->where('target_jenis', '7499');
                    $this->db->update('transaksi_payment_source', array(
                        'terbayar' => $totDppFaktur,
                        'sisa'     => $newPlafonSisa
                    ));

                    $msgSuccess = "Auto-Repair Berhasil! Plafon Induk 7499 diset ke DPP Rp " . number_format($kontrakDpp) . ", penyerapan terbayar Rp " . number_format($totDppFaktur) . ", dan seluruh formula rincian faktur 749 telah disinkronkan.";
                }
            }

            $this->db->trans_complete();

            if ($this->db->trans_status() === FALSE) {
                $msgError = "Gagal mengeksekusi perbaikan (Database Rollback).";
                $msgSuccess = "";
            }
        }

        // =========================================================================
        // 2. QUERY MASTER PROYEK & PAYMENT SOURCE DATA
        // =========================================================================
        $this->db->select("p.id, p.nama, p.harga, p.harga_nppn, p.ppn, p.customer_id, p.customer_nama, p.status, p.closing_status, p.trash, p.project_start_nomer, p.project_start_id, p.quot_nomer, p.quot_id, p.transaksi_id, p.transaksi_no, p.cabang_id, p.cabang_nama");
        $this->db->from("project_produk p");
        $this->db->where("p.trash", 0);
        $this->db->where("p.status", 1);
        if ($filterProjectId > 0) {
            $this->db->where("p.id", $filterProjectId);
        }
        if (!empty($filterSearch)) {
            $this->db->group_start();
            $this->db->like("p.nama", $filterSearch);
            $this->db->or_like("p.customer_nama", $filterSearch);
            $this->db->or_like("p.quot_nomer", $filterSearch);
            $this->db->or_like("p.project_start_nomer", $filterSearch);
            $this->db->group_end();
        }
        $this->db->order_by("p.id", "DESC");
        $this->db->limit(100);
        $projects = $this->db->get()->result_array();

        $projectIds = array();
        $allTrxIds  = array();
        foreach ($projects as $p) {
            $projectIds[] = (int)$p['id'];
            if (!empty($p['quot_id'])) $allTrxIds[] = (int)$p['quot_id'];
            if (!empty($p['project_start_id'])) $allTrxIds[] = (int)$p['project_start_id'];
            if (!empty($p['transaksi_id'])) $allTrxIds[] = (int)$p['transaksi_id'];
        }
        $projectIds = array_values(array_unique(array_filter($projectIds)));
        $allTrxIds  = array_values(array_unique(array_filter($allTrxIds)));

        // Load TPS untuk seluruh proyek ini
        $tpsMap = array();
        if (!empty($projectIds)) {
            $this->db->select("id, project_id, transaksi_id, nomer, nomer_top, jenis, target_jenis, _key, label, tagihan, terbayar, returned, diskon, sisa, ppn, ppn_sisa, dpp_ppn, dtime, cancel_dtime, cabang_id");
            $this->db->from("transaksi_payment_source");
            $this->db->where_in("project_id", $projectIds);
            $this->db->where("(cancel_dtime IS NULL OR cancel_dtime = '0000-00-00 00:00:00')", null, false);
            $this->db->order_by("id", "ASC");
            $tpsList = $this->db->get()->result_array();
            if (!empty($tpsList)) {
                foreach ($tpsList as $tRow) {
                    $pId = (int)$tRow['project_id'];
                    $tpsMap[$pId][] = $tRow;
                    if (!empty($tRow['transaksi_id'])) {
                        $allTrxIds[] = (int)$tRow['transaksi_id'];
                    }
                }
            }
        }
        $allTrxIds = array_values(array_unique(array_filter($allTrxIds)));

        // =========================================================================
        // 3. QUERY SOT JURNAL AKUNTANSI (REKENING PIUTANG 1010020010)
        // =========================================================================
        $jurnalPiutangMap = array();
        if (!empty($allTrxIds)) {
            $this->db->select("j.transaksi_id, j.rekening, SUM(j.debet) as total_debet, SUM(j.kredit) as total_kredit");
            $this->db->from("jurnal j");
            $this->db->where_in("j.transaksi_id", $allTrxIds);
            $this->db->where_in("j.rekening", array("1010020010", "2010050", "2030060"));
            $this->db->group_by(array("j.transaksi_id", "j.rekening"));
            $jRows = $this->db->get()->result_array();
            if (!empty($jRows)) {
                foreach ($jRows as $jr) {
                    $tId = (int)$jr['transaksi_id'];
                    $rek = trim((string)$jr['rekening']);
                    $jurnalPiutangMap[$tId][$rek] = array(
                        'debet'  => (float)$jr['total_debet'],
                        'kredit' => (float)$jr['total_kredit'],
                        'net'    => (float)$jr['total_debet'] - (float)$jr['total_kredit']
                    );
                }
            }
        }

        // =========================================================================
        // 4. ANALISA & EVALUASI KEABSAHAN TIAP PROYEK
        // =========================================================================
        $auditResults = array();
        $summaryKpi = array(
            'total_project'         => count($projects),
            'matched'               => 0,
            'anomaly_total'         => 0,
            'plafon_mismatch'       => 0,
            'basis_dpp_error'       => 0,
            'sisa_formula_mismatch' => 0,
            'missing_key_count'     => 0
        );

        foreach ($projects as $p) {
            $pId = (int)$p['id'];
            $pNama = !empty($p['nama']) ? $p['nama'] : "Proyek #$pId";
            $custNama = !empty($p['customer_nama']) ? $p['customer_nama'] : "-";
            $kontrakDpp = (float)$p['harga'];
            $kontrakGross = (float)$p['harga_nppn'] > 0 ? (float)$p['harga_nppn'] : round($kontrakDpp * 1.11, 2);

            $rows = isset($tpsMap[$pId]) ? $tpsMap[$pId] : array();

            $rowPlafon7499 = null;
            $rowUm04467    = null;
            $rowsRetensi7488 = array();
            $rowsFaktur749Dp = array();
            $rowsFaktur749Termin = array();
            $rowsFaktur749Retensi = array();
            $rowsFaktur749NoKey = array();

            $totFakturGross = 0;
            $totFakturDpp = 0;
            $totFakturTerbayar = 0;
            $totFakturSisa = 0;

            $hasAnomalyThisProject = false;
            $anomalyListThisProject = array();

            foreach ($rows as $r) {
                $target = trim((string)$r['target_jenis']);
                $rawKey = strtolower(trim((string)$r['_key']));
                $tagVal = (float)$r['tagihan'];
                $terbVal = (float)$r['terbayar'];
                $retVal = (float)$r['returned'];
                $diskVal = (float)$r['diskon'];
                $sisaVal = (float)$r['sisa'];
                $dppVal = (float)$r['dpp_ppn'];
                $ppnVal = (float)$r['ppn'];

                // Formula Sisa Validation
                $sisaSeharusnya = max(0, $tagVal - $terbVal - $retVal - $diskVal);
                $isFormulaError = (abs($sisaVal - $sisaSeharusnya) > 100.0);
                if ($isFormulaError) {
                    $hasAnomalyThisProject = true;
                    $summaryKpi['sisa_formula_mismatch']++;
                    $anomalyListThisProject[] = "Record #" . $r['id'] . " (" . $r['nomer'] . ") sisa tidak seimbang (Tercatat: Rp " . number_format($sisaVal) . ", Seharusnya: Rp " . number_format($sisaSeharusnya) . ").";
                }

                if ($target === '7499') {
                    $rowPlafon7499 = $r;
                    // Plafon 7499 Wajib DPP
                    if (abs($tagVal - $kontrakDpp) > 100.0) {
                        $hasAnomalyThisProject = true;
                        $summaryKpi['plafon_mismatch']++;
                        $anomalyListThisProject[] = "Plafon Induk 7499 (#" . $r['id'] . ") tidak sama dengan DPP Kontrak (Tercatat: Rp " . number_format($tagVal) . ", Kontrak DPP: Rp " . number_format($kontrakDpp) . ").";
                    }
                } elseif ($target === '04467') {
                    $rowUm04467 = $r;
                } elseif ($target === '7488') {
                    $rowsRetensi7488[] = $r;
                } elseif ($target === '749') {
                    // Faktur Kasir 749 Wajib GROSS (DPP + PPN)
                    $isStoredAsDppOnly = ($ppnVal > 0 && abs($tagVal - $dppVal) < 10) || ($kontrakDpp > 0 && abs($tagVal - ($kontrakDpp * 0.5)) < 1000 && abs($tagVal - ($kontrakGross * 0.5)) > 1000);
                    if ($isStoredAsDppOnly) {
                        $hasAnomalyThisProject = true;
                        $summaryKpi['basis_dpp_error']++;
                        $anomalyListThisProject[] = "Faktur 749 (#" . $r['id'] . ") tercatat sebagai DPP Saja (Rp " . number_format($tagVal) . "), seharusnya Gross Incl PPN.";
                    }

                    $totFakturGross += $tagVal;
                    $totFakturTerbayar += $terbVal;
                    $totFakturSisa += $sisaVal;
                    $calcDpp = ($dppVal > 0) ? $dppVal : round($tagVal / 1.11, 2);
                    $totFakturDpp += $calcDpp;

                    if ($rawKey === 'dp') {
                        $rowsFaktur749Dp[] = $r;
                    } elseif ($rawKey === 'termin') {
                        $rowsFaktur749Termin[] = $r;
                    } elseif ($rawKey === 'retensi') {
                        $rowsFaktur749Retensi[] = $r;
                    } else {
                        $hasAnomalyThisProject = true;
                        $summaryKpi['missing_key_count']++;
                        $anomalyListThisProject[] = "Faktur 749 (#" . $r['id'] . " - " . $r['nomer'] . ") memiliki kolom _key KOSONG.";
                        $rowsFaktur749NoKey[] = $r;
                    }
                }
            }

            // Validasi SOT Jurnal Akuntansi untuk Proyek Ini
            $totDebetPiutangJurnal = 0;
            $totKreditPiutangJurnal = 0;
            $relatedTrxIds = array_filter(array($p['quot_id'], $p['project_start_id'], $p['transaksi_id']));
            if (!empty($rows)) {
                foreach ($rows as $rx) {
                    if (!empty($rx['transaksi_id'])) $relatedTrxIds[] = (int)$rx['transaksi_id'];
                }
            }
            $relatedTrxIds = array_unique($relatedTrxIds);
            foreach ($relatedTrxIds as $rtId) {
                if (isset($jurnalPiutangMap[$rtId]['1010020010'])) {
                    $totDebetPiutangJurnal += $jurnalPiutangMap[$rtId]['1010020010']['debet'];
                    $totKreditPiutangJurnal += $jurnalPiutangMap[$rtId]['1010020010']['kredit'];
                }
            }
            $saldoPiutangJurnal = max(0, $totDebetPiutangJurnal - $totKreditPiutangJurnal);

            // Cek Kesesuaian Terbayar pada Induk 7499 vs Akumulasi DPP Faktur Terbit
            if ($rowPlafon7499) {
                $terbayarInduk = (float)$rowPlafon7499['terbayar'];
                if (abs($terbayarInduk - $totFakturDpp) > 100.0 && count($rows) > 1) {
                    $hasAnomalyThisProject = true;
                    $summaryKpi['plafon_mismatch']++;
                    $anomalyListThisProject[] = "Penyerapan terbayar Induk 7499 (Rp " . number_format($terbayarInduk) . ") tidak sama dengan total DPP faktur terbit (Rp " . number_format($totFakturDpp) . ").";
                }
            }

            if ($hasAnomalyThisProject) {
                $summaryKpi['anomaly_total']++;
            } else {
                $summaryKpi['matched']++;
            }

            // Filter status
            $passFilter = true;
            if ($filterStatus === 'anomaly') {
                $passFilter = $hasAnomalyThisProject;
            } elseif ($filterStatus === 'matched') {
                $passFilter = !$hasAnomalyThisProject;
            }

            if ($passFilter) {
                $auditResults[] = array(
                    'project'               => $p,
                    'kontrak_dpp'           => $kontrakDpp,
                    'kontrak_gross'         => $kontrakGross,
                    'plafon_7499'           => $rowPlafon7499,
                    'um_04467'              => $rowUm04467,
                    'retensi_7488'          => $rowsRetensi7488,
                    'faktur_749_dp'         => $rowsFaktur749Dp,
                    'faktur_749_termin'     => $rowsFaktur749Termin,
                    'faktur_749_retensi'    => $rowsFaktur749Retensi,
                    'faktur_749_nokey'      => $rowsFaktur749NoKey,
                    'tot_faktur_gross'      => $totFakturGross,
                    'tot_faktur_dpp'        => $totFakturDpp,
                    'tot_faktur_terbayar'   => $totFakturTerbayar,
                    'tot_faktur_sisa'       => $totFakturSisa,
                    'sot_jurnal_debet'      => $totDebetPiutangJurnal,
                    'sot_jurnal_kredit'     => $totKreditPiutangJurnal,
                    'sot_jurnal_piutang'    => $saldoPiutangJurnal,
                    'has_anomaly'           => $hasAnomalyThisProject,
                    'anomalies'             => $anomalyListThisProject
                );
            }
        }

        if ($isJson) {
            header('Content-Type: application/json');
            echo json_encode(array(
                'status'  => 'success',
                'summary' => $summaryKpi,
                'data'    => $auditResults
            ));
            return;
        }

        // =========================================================================
        // 5. RENDER USER INTERFACE BERSIH & ACTIONABLE
        // =========================================================================
        ?>
