            <!-- KPI SUMMARY CARDS -->
            <div class="row" style="margin-bottom: 20px;">
                <div class="col-md-3 col-sm-6">
                    <div class="card-kpi" style="border-left: 4px solid #3b82f6;">
                        <div style="font-size: 11px; font-weight: bold; color: #64748b; text-transform: uppercase;">TOTAL PROJECT DIPERIKSA</div>
                        <div style="font-size: 20px; font-weight: bold; color: #1e293b; margin-top: 4px;"><?php echo $summaryKpi['total_project']; ?> Proyek</div>
                    </div>
                </div>
                <div class="col-md-3 col-sm-6">
                    <div class="card-kpi" style="border-left: 4px solid #10b981;">
                        <div style="font-size: 11px; font-weight: bold; color: #64748b; text-transform: uppercase;">100% SINKRON & VALID</div>
                        <div style="font-size: 20px; font-weight: bold; color: #059669; margin-top: 4px;"><?php echo $summaryKpi['matched']; ?> Proyek</div>
                    </div>
                </div>
