    /**
     * Tool perbaikan invoice 4822 (invoicing) & 7499 (penerimaanprojek) yang items5_sum kosong.
     * Dual-sync: tulis ke 4822 master+child, 7499 master+child, dan project_tasklist.
     */
    public function repairInvoiceItems5SumProject()
    {
        $this->load->helper("url");
        $this->load->helper("he_url");
        $this->load->helper("he_misc");

        $filterSearch  = isset($_GET['search']) ? trim((string)$_GET['search']) : '';
        $filterStatus  = isset($_GET['filter']) ? trim((string)$_GET['filter']) : 'empty'; // empty, all, filled
        $filterLimit   = isset($_GET['limit']) ? (int)$_GET['limit'] : 50;
        if ($filterLimit < 1) $filterLimit = 50;

        $msgSuccess = "";
        $msgError   = "";

        // =========================================================================
        // 1. POST ACTION HANDLER: PERBAIKAN (INDIVIDUAL & BATCH)
        // =========================================================================
        if ($this->input->server('REQUEST_METHOD') === 'POST') {

            $action = isset($_POST['action_repair']) ? trim((string)$_POST['action_repair']) : '';

            // --- PERBAIKAN INDIVIDUAL 1-CLICK ---
            if ($action === 'fix_single') {
                $id4822  = isset($_POST['id_4822']) ? (int)$_POST['id_4822'] : 0;
                $id7499  = isset($_POST['id_7499']) ? (int)$_POST['id_7499'] : 0;
                $taskId  = isset($_POST['task_id']) ? (int)$_POST['task_id'] : 0;

                if ($id4822 > 0 && $id7499 > 0 && $taskId > 0) {
                    $result = $this->_repairItems5SumSingle($id4822, $id7499, $taskId);
                    if ($result['status'] === 'ok') {
                        $msgSuccess = $result['message'];
                    } else {
                        $msgError = $result['message'];
                    }
                } else {
                    $msgError = "Parameter tidak lengkap (id_4822=$id4822, id_7499=$id7499, task_id=$taskId).";
                }
            }

            // --- PERBAIKAN BATCH (SEMUA AUTO-FIX) ---
            if ($action === 'fix_batch') {
                $batchResult = $this->_repairItems5SumBatch();
                if ($batchResult['fixed'] > 0) {
                    $msgSuccess = "Berhasil memperbaiki " . $batchResult['fixed'] . " invoice (dari " . $batchResult['total_candidates'] . " kandidat). " . $batchResult['detail'];
                } else {
                    $msgError = "Tidak ada invoice yang dapat di-auto-fix. " . (isset($batchResult['detail']) ? $batchResult['detail'] : '');
                }
            }
        }

        // =========================================================================
        // 2. QUERY DATA: AMBIL 7499 + 4822 + TASKLIST
        // =========================================================================

        // 2A. Ambil semua 7499 master
        $this->db->select('t.id, t.nomer, t.transaksi_nilai, t.dtime, t.customers_nama, t.customers_id, r.items5_sum, r.main');
        $this->db->from('transaksi t');
        $this->db->join('transaksi_data_registry r', 'r.transaksi_id = t.id', 'left');
        $this->db->where('t.transaksi_jenis', '7499');
        $this->db->where('t.link_id', 0);
        $this->db->where('t.trash', 0);
        $this->db->where('t.transaksi_nilai >', 0);
        if (!empty($filterSearch)) {
            $this->db->group_start();
            $this->db->like('t.nomer', $filterSearch);
            $this->db->or_like('t.customers_nama', $filterSearch);
            $this->db->group_end();
        }
        $this->db->order_by('t.id', 'DESC');
        $rows7499 = $this->db->get()->result();

        // Buat map 7499 dan kumpulkan ID
        $map7499 = array();
        $ids7499 = array();
        foreach ($rows7499 as $r7) {
            $map7499[$r7->id] = $r7;
            $ids7499[] = $r7->id;
        }

        // 2B. Batch query 4822 via reference_id IN (...)
        $map4822 = array();
        if (!empty($ids7499)) {
            $chunks = array_chunk($ids7499, 200);
            foreach ($chunks as $chunk) {
                $this->db->select('t.id, t.reference_id, t.nomer, t.transaksi_nilai, r.items5_sum');
                $this->db->from('transaksi t');
                $this->db->join('transaksi_data_registry r', 'r.transaksi_id = t.id', 'left');
                $this->db->where_in('t.reference_id', $chunk);
                $this->db->where('t.transaksi_jenis', '4822');
                $this->db->where('t.link_id', 0);
                $this->db->where('t.trash', 0);
                $q4822 = $this->db->get()->result();
                foreach ($q4822 as $r4) {
                    $map4822[$r4->reference_id] = $r4;
                }
            }
        }

        // 2C. Kumpulkan projectID dari registry main 7499 dan query project_tasklist batch
        $projectIds = array();
        $mapProjectByInvoice = array(); // id7499 => projectID
        foreach ($map7499 as $id7 => $r7) {
            $mainData = array();
            if (!empty($r7->main)) {
                $mainData = @unserialize(base64_decode($r7->main));
                if (!is_array($mainData)) $mainData = array();
            }
            $pId = isset($mainData['projectID']) ? (int)$mainData['projectID'] : 0;
            $mapProjectByInvoice[$id7] = array(
                'projectID'   => $pId,
                'projectName' => isset($mainData['projectName']) ? $mainData['projectName'] : '',
                'mainData'    => $mainData
            );
            if ($pId > 0) {
                $projectIds[$pId] = $pId;
            }
        }

        // Query project_tasklist batch per projectID (grouped by produk_id)
        $mapTasklist = array(); // projectID => array of tasks
        if (!empty($projectIds)) {
            $taskChunks = array_chunk(array_values($projectIds), 200);
            foreach ($taskChunks as $tChunk) {
                $this->db->where_in('produk_id', $tChunk);
                $this->db->where('status', '1');
                $this->db->where('trash', '0');
                $tasks = $this->db->get('project_tasklist')->result();
                foreach ($tasks as $tsk) {
                    $pid = (int)$tsk->produk_id;
                    if (!isset($mapTasklist[$pid])) {
                        $mapTasklist[$pid] = array();
                    }
                    $mapTasklist[$pid][] = $tsk;
                }
            }
        }

        // =========================================================================
        // 3. BANGUN TABEL DATA + KPI
        // =========================================================================
        $tableData = array();
        $kpiTotal = 0;
        $kpiEmpty4822 = 0;
        $kpiFilled = 0;
        $kpiAutoFix = 0;
        $kpiNominalTerdampak = 0;

        foreach ($map7499 as $id7 => $r7) {
            if (!isset($map4822[$id7])) continue; // tidak ada 4822 terkait

            $r4 = $map4822[$id7];
            $kpiTotal++;

            // Cek items5_sum 4822
            $isEmpty4822 = true;
            $count4822Tasks = 0;
            if (!empty($r4->items5_sum)) {
                $dec = @unserialize(base64_decode($r4->items5_sum));
                if (is_array($dec) && count($dec) > 0) {
                    $isEmpty4822 = false;
                    $count4822Tasks = count($dec);
                }
            }

            // Cek items5_sum 7499
            $isEmpty7499 = true;
            if (!empty($r7->items5_sum)) {
                $dec7 = @unserialize(base64_decode($r7->items5_sum));
                if (is_array($dec7) && count($dec7) > 0) {
                    $isEmpty7499 = false;
                }
            }

            // Project info
            $projInfo = isset($mapProjectByInvoice[$id7]) ? $mapProjectByInvoice[$id7] : array('projectID' => 0, 'projectName' => '', 'mainData' => array());
            $pId = $projInfo['projectID'];
            $pName = $projInfo['projectName'];

            // Tasklist info
            $taskArr = isset($mapTasklist[$pId]) ? $mapTasklist[$pId] : array();
            $taskCount = count($taskArr);
            $taskTotalNilai = 0;
            foreach ($taskArr as $tk) {
                $taskTotalNilai += (float)$tk->nilai_sub_fase;
            }

            // Analisis kecocokan
            $matchType = 'no_match';
            $matchTaskId = 0;
            $matchTaskNama = '';
            $invoiceNilai = (float)$r4->transaksi_nilai;

            if ($taskCount === 1) {
                $matchType = 'single_task';
                $matchTaskId = (int)$taskArr[0]->id;
                $matchTaskNama = $taskArr[0]->nama;
            } elseif ($taskCount > 1) {
                // Cari exact match
                foreach ($taskArr as $tk) {
                    if (abs((float)$tk->nilai_sub_fase - $invoiceNilai) < 1) {
                        $matchType = 'exact_match';
                        $matchTaskId = (int)$tk->id;
                        $matchTaskNama = $tk->nama;
                        break;
                    }
                }
                if ($matchType === 'no_match') {
                    $matchType = 'multi_no_match';
                }
            } else {
                $matchType = 'no_task';
            }

            // KPI
            if ($isEmpty4822) {
                $kpiEmpty4822++;
                $kpiNominalTerdampak += $invoiceNilai;
                if ($matchType === 'single_task' || $matchType === 'exact_match') {
                    $kpiAutoFix++;
                }
            } else {
                $kpiFilled++;
            }

            // Filter status
            if ($filterStatus === 'empty' && !$isEmpty4822) continue;
            if ($filterStatus === 'filled' && $isEmpty4822) continue;

            // Filter search (tambahan: nama proyek)
            if (!empty($filterSearch)) {
                $searchLower = strtolower($filterSearch);
                $haystack = strtolower($r7->nomer . ' ' . $r7->customers_nama . ' ' . $pName . ' ' . $r4->nomer);
                if (strpos($haystack, $searchLower) === false) continue;
            }

            $tableData[] = array(
                'id_4822'       => (int)$r4->id,
                'nomer_4822'    => $r4->nomer,
                'id_7499'       => (int)$id7,
                'nomer_7499'    => $r7->nomer,
                'customer'      => $r7->customers_nama,
                'dtime'         => $r7->dtime,
                'nilai'         => $invoiceNilai,
                'project_id'    => $pId,
                'project_nama'  => $pName,
                'empty_4822'    => $isEmpty4822,
                'count_4822'    => $count4822Tasks,
                'empty_7499'    => $isEmpty7499,
                'task_count'    => $taskCount,
                'task_total'    => $taskTotalNilai,
                'match_type'    => $matchType,
                'match_task_id' => $matchTaskId,
                'match_task_nama' => $matchTaskNama,
                'tasks'         => $taskArr
            );
        }

        // Limit tampilan
        $totalFiltered = count($tableData);
        $tableDataLimited = array_slice($tableData, 0, $filterLimit);

