    /**
     * AJAX endpoint: ambil tasklist untuk modal pilih task manual.
     */
    public function repairInvoiceItems5SumProject_ajaxTasks()
    {
        $projectId = isset($_GET['project_id']) ? (int)$_GET['project_id'] : 0;
        $tasks = array();
        if ($projectId > 0) {
            $this->db->where('produk_id', $projectId);
            $this->db->where('status', '1');
            $this->db->where('trash', '0');
            $this->db->order_by('id', 'ASC');
            $rows = $this->db->get('project_tasklist')->result();
            foreach ($rows as $r) {
                $tasks[] = array(
                    'id'             => (int)$r->id,
                    'nama'           => $r->nama,
                    'no_spk'         => isset($r->no_spk) ? $r->no_spk : '',
                    'nilai_sub_fase' => (float)$r->nilai_sub_fase,
                    'debet'          => (float)$r->debet,
                    'sisa'           => (float)$r->sisa,
                    'invoiced'       => isset($r->invoiced) ? $r->invoiced : '',
                    'inv_trx_id'     => isset($r->inv_trx_id) ? $r->inv_trx_id : 0
                );
            }
        }
        header('Content-Type: application/json');
        echo json_encode(array('tasks' => $tasks));
    }

    /**
     * Internal: Perbaiki items5_sum untuk 1 pasangan 4822+7499.
     * Menulis ke: 4822 master, 4822 child, 7499 master, 7499 child, project_tasklist.
     *
     * @param int $id4822  ID transaksi 4822 master (link_id=0)
     * @param int $id7499  ID transaksi 7499 master (link_id=0)
     * @param int $taskId  ID task di project_tasklist yang dipilih
     * @return array  array('status' => 'ok'|'error', 'message' => '...')
     */
    // START OF COMPLETE REPEATED LOGIC
    private function _repairItems5SumSingle($id4822, $id7499, $taskId)
    {
        // A. Ambil data transaksi 7499 master
        $this->db->select('t.id, t.nomer, t.transaksi_nilai, t.dtime, t.customers_id, t.customers_nama, t.oleh_id, t.oleh_nama, r.main');
        $this->db->from('transaksi t');
        $this->db->join('transaksi_data_registry r', 'r.transaksi_id = t.id', 'left');
        $this->db->where('t.id', $id7499);
        $row7499 = $this->db->get()->row();
        if (!$row7499) {
            return array('status' => 'error', 'message' => "Transaksi 7499 #$id7499 tidak ditemukan.");
        }

        // B. Ambil data transaksi 4822 master
        $this->db->where('id', $id4822);
        $row4822 = $this->db->get('transaksi')->row();
        if (!$row4822) {
            return array('status' => 'error', 'message' => "Transaksi 4822 #$id4822 tidak ditemukan.");
        }

        // C. Ambil task dari project_tasklist
        $this->db->where('id', $taskId);
        $task = $this->db->get('project_tasklist')->row();
        if (!$task) {
            return array('status' => 'error', 'message' => "Task #$taskId tidak ditemukan di project_tasklist.");
        }

        // D. Decode main dari 7499 untuk info project
        $mainData = array();
        if (!empty($row7499->main)) {
            $mainData = @unserialize(base64_decode($row7499->main));
            if (!is_array($mainData)) $mainData = array();
        }

        // E. Ambil bahan_baku dari project_sub_tasklist_komposisi / project_komposisi_sub_workoder
        $arrBahanBaku = array('produk' => array(), 'biaya' => array());
        $arrKelebihan = array();
        $idProject = isset($task->produk_id) ? (int)$task->produk_id : 0;
        $noSpk = isset($task->no_spk) ? trim((string)$task->no_spk) : '';

        // 1. Coba ambil dari project_sub_tasklist_komposisi (prioritaskan no_spk jika ada)
        $this->db->where('produk_id', $idProject);
        if ($noSpk !== '') {
            $this->db->where('no_spk', $noSpk);
        }
        $this->db->where('status', '1');
        $this->db->where('trash', '0');
        $this->db->where('(kelebihan = 0 OR kelebihan IS NULL)');
        $komposisiRows = $this->db->get('project_sub_tasklist_komposisi')->result();

        // 2. Jika dengan no_spk kosong, coba query tanpa no_spk di project_sub_tasklist_komposisi
        if (empty($komposisiRows) && $idProject > 0) {
            $this->db->where('produk_id', $idProject);
            $this->db->where('status', '1');
            $this->db->where('trash', '0');
            $this->db->where('(kelebihan = 0 OR kelebihan IS NULL)');
            $komposisiRows = $this->db->get('project_sub_tasklist_komposisi')->result();
        }

        // 3. Jika masih kosong, coba dari project_komposisi_sub_workoder
        if (empty($komposisiRows) && $idProject > 0) {
            $this->db->where('produk_id', $idProject);
            if ($noSpk !== '') {
                $this->db->where('no_spk', $noSpk);
            }
            $this->db->where('status', '1');
            $this->db->where('trash', '0');
            $komposisiRows = $this->db->get('project_komposisi_sub_workoder')->result();
        }

        // 4. Jika masih kosong di BOM dengan no_spk, coba tanpa no_spk
        if (empty($komposisiRows) && $idProject > 0) {
            $this->db->where('produk_id', $idProject);
            $this->db->where('status', '1');
            $this->db->where('trash', '0');
            $komposisiRows = $this->db->get('project_komposisi_sub_workoder')->result();
        }

        $nominalBilled = (float)$row7499->transaksi_nilai;

        // 5. Masukkan ke $arrBahanBaku dengan pemisahan produk vs biaya
        if (!empty($komposisiRows)) {
            foreach ($komposisiRows as $komp) {
                $jns = (isset($komp->jenis) && $komp->jenis === 'produk') ? 'produk' : 'biaya';
                $pDasarId = !empty($komp->produk_dasar_id) ? (int)$komp->produk_dasar_id : (int)$komp->id;
                $kompArr = (array)$komp;

                // Pastikan key yang wajib dibaca oleh Printing::viewReceiptReg() terisi lengkap
                if (!isset($kompArr['produk_dasar_nama']) || empty($kompArr['produk_dasar_nama'])) {
                    $kompArr['produk_dasar_nama'] = isset($komp->nama) ? $komp->nama : (isset($task->nama) ? $task->nama : 'Barang / Biaya Proyek');
                }
                if (!isset($kompArr['jml']) || (float)$kompArr['jml'] == 0) {
                    $kompArr['jml'] = 1;
                }
                if (!isset($kompArr['harga']) || (float)$kompArr['harga'] == 0) {
                    $kompArr['harga'] = (float)$nominalBilled;
                }
                if (!isset($kompArr['saldo']) || (float)$kompArr['saldo'] == 0) {
                    $kompArr['saldo'] = isset($kompArr['nilai']) && (float)$kompArr['nilai'] > 0 ? (float)$kompArr['nilai'] : (float)$kompArr['harga'];
                }
                if (!isset($kompArr['satuan']) || empty($kompArr['satuan'])) {
                    $kompArr['satuan'] = 'Unit';
                }

                $arrBahanBaku[$jns][$pDasarId] = $kompArr;
            }
        } else {
            // 6. Fallback jika benar-benar tidak ada komposisi: buat 1 baris biaya jasa senilai DPP
            $arrBahanBaku['biaya'][$task->id] = array(
                'id'                => $task->id,
                'jenis'             => 'biaya',
                'produk_dasar_id'   => 0,
                'produk_dasar_nama' => !empty($task->nama) ? $task->nama : 'JASA PEKERJAAN PROYEK',
                'jml'               => 1,
                'harga'             => $nominalBilled,
                'debet'             => $nominalBilled,
                'kredit'            => 0,
                'saldo'             => $nominalBilled,
                'qty_debet'         => 1,
                'qty_kredit'        => 0,
                'qty_saldo'         => 1,
                'satuan'            => 'LOT',
                'cat_nama'          => 'jasa',
                'status'            => 1,
                'trash'             => 0,
            );
        }

        // F. Bangun items5_sum
        $projName = isset($mainData['projectName']) && !empty($mainData['projectName'])
            ? $mainData['projectName']
            : (isset($mainData['project_nama']) && !empty($mainData['project_nama'])
                ? $mainData['project_nama']
                : (isset($task->nama) ? $task->nama : ''));

        $items5_sum = array();
        $items5_sum[$task->id] = array(
            'id'                     => $task->id,
            'nama'                   => $task->nama,
            'nomer'                  => isset($task->nomer) ? $task->nomer : '',
            'cabang_id'              => isset($task->cabang_id) ? $task->cabang_id : '',
            'produk_paket_id'        => isset($task->produk_paket_id) ? $task->produk_paket_id : '',
            'produk_paket_nama'      => isset($task->produk_paket_nama) ? $task->produk_paket_nama : '',
            'no_kontrak'             => isset($task->no_kontrak) ? $task->no_kontrak : '',
            'tgl_kontrak'            => isset($task->tgl_kontrak) ? $task->tgl_kontrak : '',
            'nilai_kontrak'          => isset($task->nilai_kontrak) ? $task->nilai_kontrak : 0,
            'dtime_spk'              => isset($task->dtime_spk) ? $task->dtime_spk : '',
            'no_spk'                 => isset($task->no_spk) ? $task->no_spk : '',
            'no_spk2'                => isset($task->no_spk2) ? $task->no_spk2 : '',
            'no_pre_spk'             => isset($task->no_pre_spk) ? $task->no_pre_spk : '',
            'persen_sub'             => isset($task->persen_sub) ? $task->persen_sub : 100,
            'nilai_sub_fase'         => isset($task->nilai_sub_fase) ? $task->nilai_sub_fase : 0,
            'debet'                  => $nominalBilled,
            'kredit'                 => isset($task->nilai_sub_fase) ? $task->nilai_sub_fase : 0,
            'sisa'                   => max(0, (isset($task->nilai_sub_fase) ? (float)$task->nilai_sub_fase : 0) - $nominalBilled),
            'material'               => isset($task->material) ? $task->material : 0,
            'fase_id'                => isset($task->fase_id) ? $task->fase_id : 0,
            'sub_fase_id'            => isset($task->sub_fase_id) ? $task->sub_fase_id : 0,
            'produk_id'              => isset($task->produk_id) ? $task->produk_id : 0,
            'pre_spk_validasi_img'   => isset($task->pre_spk_validasi_img) ? $task->pre_spk_validasi_img : '',
            'produk_nama'            => isset($task->produk_nama) ? $task->produk_nama : '',
            'type_pelaksana'         => isset($task->type_pelaksana) ? $task->type_pelaksana : '',
            'employee_id'            => isset($task->employee_id) ? $task->employee_id : '',
            'employee_nama'          => isset($task->employee_nama) ? $task->employee_nama : '',
            'project_workorder_id'   => isset($task->project_workorder_id) ? $task->project_workorder_id : '',
            'project_workorder_nama' => isset($task->project_workorder_nama) ? $task->project_workorder_nama : '',
            'dtime'                  => isset($task->dtime) ? $task->dtime : '',
            'nilai'                  => isset($task->nilai) ? $task->nilai : '',
            'file'                   => isset($task->file) ? $task->file : '',
            'status'                 => isset($task->status) ? $task->status : 1,
            'trash'                  => 0,
            'input_property'         => isset($task->input_property) ? $task->input_property : '',
            'fase_nama'              => isset($task->fase_nama) ? $task->fase_nama : '',
            'dtime_start'            => isset($task->dtime_start) ? $task->dtime_start : '',
            'dtime_end'              => isset($task->dtime_end) ? $task->dtime_end : '',
            'oleh_id'                => isset($task->oleh_id) ? $task->oleh_id : '',
            'oleh_nama'              => isset($task->oleh_nama) ? $task->oleh_nama : '',
            'progress_id'            => isset($task->progress_id) ? $task->progress_id : 0,
            'progress_nama'          => isset($task->progress_nama) ? $task->progress_nama : '',
            'progress_percent'       => isset($task->progress_percent) ? $task->progress_percent : 0,
            'qc_nomer'               => isset($task->qc_nomer) ? $task->qc_nomer : '',
            'qc_auth_id'             => isset($task->qc_auth_id) ? $task->qc_auth_id : '',
            'qc_auth_nama'           => isset($task->qc_auth_nama) ? $task->qc_auth_nama : '',
            'qc_dtime'               => isset($task->qc_dtime) ? $task->qc_dtime : '',
            'distribute_percent'     => isset($task->distribute_percent) ? $task->distribute_percent : 0,
            'owner_nama'             => isset($task->owner_nama) ? $task->owner_nama : '',
            'dtime_diff'             => isset($task->dtime_diff) ? $task->dtime_diff : '',
            'invoiced'               => $row7499->nomer,
            'inv_dtime'              => $row7499->dtime,
            'inv_trx_id'             => $id7499,
            'post_biaya_id'          => isset($task->post_biaya_id) ? $task->post_biaya_id : 0,
            'post_biaya_no'          => isset($task->post_biaya_no) ? $task->post_biaya_no : '',
            'post_biaya_dtime'       => isset($task->post_biaya_dtime) ? $task->post_biaya_dtime : '',
            'post_return_id'         => isset($task->post_return_id) ? $task->post_return_id : 0,
            'post_return_no'         => isset($task->post_return_no) ? $task->post_return_no : '',
            'post_return_dtime'      => isset($task->post_return_dtime) ? $task->post_return_dtime : '',
            'post_return_cli'        => isset($task->post_return_cli) ? $task->post_return_cli : 0,
            'approved'               => isset($task->approved) ? $task->approved : '',
            'approval_id'            => isset($task->approval_id) ? $task->approval_id : '',
            'approval_nama'          => isset($task->approval_nama) ? $task->approval_nama : '',
            'approval_dtime'         => isset($task->approval_dtime) ? $task->approval_dtime : '',
            'approval_nilai'         => isset($task->approval_nilai) ? $task->approval_nilai : '',
            'reject_no'              => isset($task->reject_no) ? $task->reject_no : '',
            'approve_no'             => isset($task->approve_no) ? $task->approve_no : '',
            'gudang_wo'              => isset($task->gudang_wo) ? $task->gudang_wo : '',
            'bahan_baku'             => $arrBahanBaku,
            'kelebihan'              => $arrKelebihan,
            'harga'                  => $nominalBilled,
            'harga_nppn'             => round($nominalBilled * 1.11, 2),
            'persen'                 => 100,
            'olehID'                 => isset($row7499->oleh_id) ? $row7499->oleh_id : (isset($task->oleh_id) ? $task->oleh_id : 0),
            'olehName'               => isset($row7499->oleh_nama) ? $row7499->oleh_nama : (isset($task->oleh_nama) ? $task->oleh_nama : ''),
            'sellerID'               => 0,
            'sellerName'             => isset($row7499->oleh_nama) ? $row7499->oleh_nama : '',
            'pihakID'                => isset($row7499->customers_id) ? $row7499->customers_id : 0,
            'pihakName'              => isset($row7499->customers_nama) ? $row7499->customers_nama : '',
            'customerID'             => isset($row7499->customers_id) ? $row7499->customers_id : 0,
            'customerName'           => isset($row7499->customers_nama) ? $row7499->customers_nama : '',
            'pihakMainName'          => '',
            'placeID'                => isset($task->cabang_id) ? $task->cabang_id : 1,
            'placeName'              => isset($task->cabang_nama) ? $task->cabang_nama : 'CABANG PINANG',
            'cabangID'               => isset($task->cabang_id) ? $task->cabang_id : 1,
            'cabangName'             => isset($task->cabang_nama) ? $task->cabang_nama : 'CABANG PINANG',
            'gudangID'               => -10,
            'gudangName'             => 'Gudang Reguler Cabang #' . (isset($task->cabang_id) ? $task->cabang_id : 1),
            'jenisTr'                => '4822',
            'jenisTrMaster'          => '4822',
            'valasDetails'           => 0,
            'ppnFactor'              => 11,
            'pph_23'                 => 0,
            'terbayar_pph23'         => 0,
            'cashMethode'            => 'none',
            'projectID'              => $idProject,
            'projectName'            => $projName,
            'transaksi_id'           => $id7499,
            'currentID'              => $id7499,
        );

        $encodedItems5 = base64_encode(serialize($items5_sum));

        // G. DB Transaction: tulis ke 5 titik
        $this->db->trans_start();

        // G1. Update registry 4822 master
        $this->db->where('transaksi_id', $id4822);
        $this->db->update('transaksi_data_registry', array('items5_sum' => $encodedItems5));

        // G2. Update registry 7499 master
        $this->db->where('transaksi_id', $id7499);
        $this->db->update('transaksi_data_registry', array('items5_sum' => $encodedItems5));

        // G3. Update registry 4822 child (link_id = id4822)
        $this->db->select('id');
        $this->db->where('reference_id', $id7499);
        $this->db->where('transaksi_jenis', '4822');
        $this->db->where('link_id >', 0);
        $this->db->where('trash', 0);
        $children4822 = $this->db->get('transaksi')->result();
        foreach ($children4822 as $ch) {
            $this->db->where('transaksi_id', $ch->id);
            $this->db->update('transaksi_data_registry', array('items5_sum' => $encodedItems5));
        }

        // G4. Update registry 7499 child (link_id = id7499)
        $this->db->select('id');
        $this->db->where('transaksi_jenis', '7499');
        $this->db->where('link_id', $id7499);
        $this->db->where('trash', 0);
        $children7499 = $this->db->get('transaksi')->result();
        foreach ($children7499 as $ch7) {
            $this->db->where('transaksi_id', $ch7->id);
            $this->db->update('transaksi_data_registry', array('items5_sum' => $encodedItems5));
        }

        // G5. Update project_tasklist: debet, sisa, invoiced, inv_trx_id, inv_dtime
        $existingInvoiced = isset($task->invoiced) ? trim((string)$task->invoiced) : '';
        $existingInvTrxId = isset($task->inv_trx_id) ? trim((string)$task->inv_trx_id) : '';
        $existingInvDtime = isset($task->inv_dtime) ? trim((string)$task->inv_dtime) : '';

        // Tangani invoiced nomor agar bersih (hilangkan awalan 0)
        if ($existingInvoiced === '' || $existingInvoiced === '0') {
            $newInvoiced = $row7499->nomer;
        } else {
            $invParts = explode(',', $existingInvoiced);
            $cleanInvParts = array();
            foreach ($invParts as $ip) {
                $ip = trim($ip);
                if ($ip !== '' && $ip !== '0') $cleanInvParts[] = $ip;
            }
            if (!in_array($row7499->nomer, $cleanInvParts)) {
                $cleanInvParts[] = $row7499->nomer;
            }
            $newInvoiced = implode(',', $cleanInvParts);
        }

        // Tangani inv_trx_id
        $alreadyInvoiced = false;
        if ($existingInvTrxId === '' || $existingInvTrxId === '0') {
            $newInvTrxId = (string)$id7499;
        } else {
            $trxParts = explode(',', $existingInvTrxId);
            $cleanTrxParts = array();
            foreach ($trxParts as $tp) {
                $tp = trim($tp);
                if ($tp !== '' && $tp !== '0') $cleanTrxParts[] = $tp;
            }
            if (in_array((string)$id7499, $cleanTrxParts)) {
                $alreadyInvoiced = true;
            } else {
                $cleanTrxParts[] = (string)$id7499;
            }
            $newInvTrxId = implode(',', $cleanTrxParts);
        }

        // Tangani inv_dtime
        if ($existingInvDtime === '' || $existingInvDtime === '0') {
            $newInvDtime = $row7499->dtime;
        } else {
            $dtParts = explode(',', $existingInvDtime);
            $cleanDtParts = array();
            foreach ($dtParts as $dp) {
                $dp = trim($dp);
                if ($dp !== '' && $dp !== '0') $cleanDtParts[] = $dp;
            }
            if (!in_array($row7499->dtime, $cleanDtParts)) {
                $cleanDtParts[] = $row7499->dtime;
            }
            $newInvDtime = implode(',', $cleanDtParts);
        }

        // Hitung debet baru: jika transaksi ini sudah pernah tercatat, jangan ditambahkan ganda
        $existingDebet = isset($task->debet) ? (float)$task->debet : 0;
        $newDebet = $alreadyInvoiced ? $existingDebet : ($existingDebet + $nominalBilled);
        $nilaiSubFase = isset($task->nilai_sub_fase) ? (float)$task->nilai_sub_fase : 0;
        $newSisa = max(0, $nilaiSubFase - $newDebet);

        $this->db->where('id', $taskId);
        $this->db->update('project_tasklist', array(
            'debet'       => $newDebet,
            'sisa'        => $newSisa,
            'invoiced'    => $newInvoiced,
            'inv_trx_id'  => $newInvTrxId,
            'inv_dtime'   => $newInvDtime,
        ));

        $this->db->trans_complete();

        if ($this->db->trans_status() === false) {
            return array('status' => 'error', 'message' => "Gagal menyimpan. Transaksi database di-rollback.");
        }

        return array(
            'status'  => 'ok',
            'message' => "Berhasil memperbaiki items5_sum untuk 4822 #$id4822 + 7499 #$id7499 + Task #$taskId. Debet: Rp " . number_format($newDebet) . ", Sisa: Rp " . number_format($newSisa) . "."
        );
    }
    // END OF COMPLETE REPEATED LOGIC

    /**
     * Internal: Perbaiki batch semua invoice yang bisa auto-fix (single task / exact match).
     * @return array  array('fixed' => int, 'total_candidates' => int, 'detail' => string)
     */
    private function _repairItems5SumBatch()
    {
        // Ambil semua 7499 master
        $this->db->select('t.id, t.nomer, t.transaksi_nilai, t.dtime, t.customers_id, t.customers_nama, r.items5_sum, r.main');
        $this->db->from('transaksi t');
        $this->db->join('transaksi_data_registry r', 'r.transaksi_id = t.id', 'left');
        $this->db->where('t.transaksi_jenis', '7499');
        $this->db->where('t.link_id', 0);
        $this->db->where('t.trash', 0);
        $this->db->where('t.transaksi_nilai >', 0);
        $this->db->order_by('t.id', 'DESC');
        $rows7499 = $this->db->get()->result();

        $map7499 = array();
        $ids7499 = array();
        foreach ($rows7499 as $r7) {
            $map7499[$r7->id] = $r7;
            $ids7499[] = $r7->id;
        }

        // Batch query 4822
        $map4822 = array();
        if (!empty($ids7499)) {
            $chunks = array_chunk($ids7499, 200);
            foreach ($chunks as $chunk) {
                $this->db->select('t.id, t.reference_id, t.nomer, t.transaksi_nilai, r.items5_sum');
                $this->db->from('transaksi t');
                $this->db->join('transaksi_data_registry r', 'r.transaksi_id = t.id', 'left');
                $this->db->where_in('t.reference_id', $chunk);
                $this->db->where('t.transaksi_jenis', '4822');
                $this->db->where('t.link_id', 0);
                $this->db->where('t.trash', 0);
                $q4822 = $this->db->get()->result();
                foreach ($q4822 as $r4) {
                    $map4822[$r4->reference_id] = $r4;
                }
            }
        }

        // Kumpulkan projectID dan query tasklist batch
        $projectIds = array();
        $mapProjectByInvoice = array();
        foreach ($map7499 as $id7 => $r7) {
            $mainData = array();
            if (!empty($r7->main)) {
                $mainData = @unserialize(base64_decode($r7->main));
                if (!is_array($mainData)) $mainData = array();
            }
            $pId = isset($mainData['projectID']) ? (int)$mainData['projectID'] : 0;
            $mapProjectByInvoice[$id7] = $pId;
            if ($pId > 0) $projectIds[$pId] = $pId;
        }

        $mapTasklist = array();
        if (!empty($projectIds)) {
            $taskChunks = array_chunk(array_values($projectIds), 200);
            foreach ($taskChunks as $tChunk) {
                $this->db->where_in('produk_id', $tChunk);
                $this->db->where('status', '1');
                $this->db->where('trash', '0');
                $tasks = $this->db->get('project_tasklist')->result();
                foreach ($tasks as $tsk) {
                    $pid = (int)$tsk->produk_id;
                    if (!isset($mapTasklist[$pid])) $mapTasklist[$pid] = array();
                    $mapTasklist[$pid][] = $tsk;
