        // Iterasi dan perbaiki yang auto-fixable
        $fixed = 0;
        $candidates = 0;
        $errors = array();

        foreach ($map7499 as $id7 => $r7) {
            if (!isset($map4822[$id7])) continue;
            $r4 = $map4822[$id7];

