            }
            if (!$isEmpty4822) continue; // sudah terisi, skip

            $pId = isset($mapProjectByInvoice[$id7]) ? $mapProjectByInvoice[$id7] : 0;
            $taskArr = isset($mapTasklist[$pId]) ? $mapTasklist[$pId] : array();
            $taskCount = count($taskArr);
